function clampGameZoom(value: unknown): number {
  const parsed = typeof value === "number" && Number.isFinite(value) ? value : 1;
  const rounded = Math.round(parsed * 100) / 100;
  return Math.min(GAME_ZOOM_MAX, Math.max(GAME_ZOOM_MIN, rounded));
}

type ReplayRecorderFormat = {
  recorderMimeType: string;
  fileMimeType: ReplayVideoMimeType;
  codec: string;
};

function supportedReplayVideoFormats(includeAudio = false): ReplayRecorderFormat[] {
  const videoOnlyCandidates = [
    { recorderMimeType: "video/webm;codecs=vp8", fileMimeType: "video/webm" as const, codec: "VP8 WebM" },
    { recorderMimeType: "video/webm;codecs=vp9", fileMimeType: "video/webm" as const, codec: "VP9 WebM" },
    { recorderMimeType: "video/webm", fileMimeType: "video/webm" as const, codec: "WebM" },
    { recorderMimeType: "video/mp4;codecs=avc1.640028", fileMimeType: "video/mp4" as const, codec: "H.264 MP4 fallback" },
    { recorderMimeType: "video/mp4;codecs=avc1.4D4028", fileMimeType: "video/mp4" as const, codec: "H.264 MP4 fallback" },
    { recorderMimeType: "video/mp4", fileMimeType: "video/mp4" as const, codec: "MP4 fallback" }
  ];
  const audioCandidates = [
    { recorderMimeType: "video/webm;codecs=vp8,opus", fileMimeType: "video/webm" as const, codec: "VP8 WebM + audio" },
    { recorderMimeType: "video/webm;codecs=vp9,opus", fileMimeType: "video/webm" as const, codec: "VP9 WebM + audio" },
    { recorderMimeType: "video/mp4;codecs=avc1.640028,mp4a.40.2", fileMimeType: "video/mp4" as const, codec: "H.264 MP4 + audio fallback" },
    { recorderMimeType: "video/mp4;codecs=avc1.4D4028,mp4a.40.2", fileMimeType: "video/mp4" as const, codec: "H.264 MP4 + audio fallback" }
  ];
  const candidates = includeAudio ? [...audioCandidates, ...videoOnlyCandidates] : videoOnlyCandidates;
  return candidates.filter((candidate) => MediaRecorder.isTypeSupported(candidate.recorderMimeType));
}

function normalizeReplayShadowClipSeconds(value: unknown): number {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) {
    return 60;
  }
  return Math.max(15, Math.min(600, Math.round(numeric)));
}

async function createReplayMicrophoneStream(microphoneDeviceId: string): Promise<MediaStream> {
  const audio: MediaTrackConstraints = {
    ...(microphoneDeviceId ? { deviceId: { exact: microphoneDeviceId } } : {}),
    echoCancellation: false,
    noiseSuppression: false,
    autoGainControl: false,
    channelCount: 1,
    sampleRate: 48_000,
    sampleSize: 16
  };
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio });
    await Promise.all(stream.getAudioTracks().map((track) => track.applyConstraints(audio).catch(() => undefined)));
    return stream;
  } catch {
    return navigator.mediaDevices.getUserMedia({
      audio: microphoneDeviceId ? { deviceId: { exact: microphoneDeviceId } } : true
    });
  }
}

function formatBytes(value: number): string {
  if (!Number.isFinite(value) || value <= 0) {
    return "0 MB";
  }
  if (value >= 1024 * 1024 * 1024) {
    return `${(value / (1024 * 1024 * 1024)).toFixed(2)} GB`;
  }
  return `${Math.max(0.1, value / (1024 * 1024)).toFixed(1)} MB`;
}

