  async function enableHomeDeckThemeFromIntro() {
    if (homeThemeIntroBusy) return;
    setHomeThemeIntroBusy(true);
    try {
      await saveSettings({ homeDeckThemeEnabled: true });
      finishHomeThemeIntro();
      showActionFeedback("Home will now follow your active deck's two-domain palette.");
    } catch (error) {
      showActionFeedback(error instanceof Error ? error.message : "The Home theme could not be enabled.", 5_000);
    } finally {
      setHomeThemeIntroBusy(false);
    }
  }

  function openHomeThemeSettingsFromIntro() {
    finishHomeThemeIntro();
    openView("settings");
    window.setTimeout(() => {
      const card = document.getElementById("home-theme-settings");
      card?.scrollIntoView({ behavior: "smooth", block: "center" });
      card?.querySelector<HTMLElement>('input[type="checkbox"]')?.focus({ preventScroll: true });
    }, 120);
  }

  function persistFirstMatchOnboarding(next: FirstMatchOnboardingState) {
    writeFirstMatchOnboardingState(next);
    setFirstMatchOnboarding(next);
  }

  function updateGuidedTour(next: GuidedTourState) {
    if (!guidedTourReplayRef.current) {
      writeGuidedTourState(next);
    }
    setGuidedTourState(next.status === "active" ? next : null);
  }

  function finishGuidedTour(next: GuidedTourState) {
    if (!guidedTourReplayRef.current) {
      writeGuidedTourState(next);
      persistFirstMatchOnboarding(firstMatchOnboardingAfterTour(firstMatchOnboarding, next.status, matches));
    }
    setGuidedTourState(null);
    const restore = guidedTourRestoreRef.current;
    if (guidedTourReplayRef.current && restore) {
      openView(restore.view);
      setSidebarCollapsed(restore.sidebarCollapsed);
      setExpandedNavGroup(restore.expandedNavGroup);
    } else {
      openView("home");
      setExpandedNavGroup(null);
    }
    guidedTourReplayRef.current = false;
    guidedTourRestoreRef.current = null;
    showActionFeedback(next.status === "completed" ? "Guided tour complete." : "Guided tour skipped. You can replay it from Settings.");
  }

  useEffect(() => {
    const disclosure = owningNavigationDisclosure({
      view: activeView,
      deckFocus: deckFocusTarget,
      communityTab: activeCommunityTab
    });
    if (disclosure) {
      setExpandedNavGroup(disclosure.id);
    }
  }, [activeCommunityTab, activeView, deckFocusTarget]);

  useEffect(() => {
    activeViewRef.current = activeView;
  }, [activeView]);

  useEffect(() => window.riftlite.onAppNavigate((request) => {
    if (request.view === "hubs") {
      setActiveView("hubs");
      return;
    }
    setActiveView("account");
  }), []);

  useEffect(() => window.riftlite.onReplayMp4ExportProgress((progress) => {
    if (retiredMp4ExportIdsRef.current.has(progress.exportId)) {
      return;
    }
    const terminal = progress.stage === "completed" || progress.stage === "failed";
    const staleUnboundIndex = settledUnboundMp4RequestsRef.current.findIndex((request) =>
      request.requestId === progress.requestId
      && request.replayId === progress.replayId
      && request.kind === progress.kind
    );
    const retireStaleUnboundProgress = (): void => {
      if (staleUnboundIndex >= 0) {
        settledUnboundMp4RequestsRef.current.splice(staleUnboundIndex, 1);
      }
      retiredMp4ExportIdsRef.current.add(progress.exportId);
      while (retiredMp4ExportIdsRef.current.size > 64) {
        const oldest = retiredMp4ExportIdsRef.current.values().next().value as string | undefined;
        if (!oldest) break;
        retiredMp4ExportIdsRef.current.delete(oldest);
      }
    };
    const active = activeMp4ExportRef.current;
    if (!active) {
      if (staleUnboundIndex >= 0) {
        retireStaleUnboundProgress();
      }
      return;
    }
    if (active.requestId !== progress.requestId || active.replayId !== progress.replayId || active.kind !== progress.kind) {
      if (staleUnboundIndex >= 0) {
        retireStaleUnboundProgress();
      }
      return;
    }
    if (active.exportId && active.exportId !== progress.exportId) {
      if (staleUnboundIndex >= 0) {
        retireStaleUnboundProgress();
      }
      return;
    }
    if (!active.exportId && terminal && staleUnboundIndex >= 0) {
      retireStaleUnboundProgress();
      return;
    }
    if (!active.exportId && !terminal && staleUnboundIndex >= 0) {
      settledUnboundMp4RequestsRef.current.splice(staleUnboundIndex, 1);
    }
    active.exportId = progress.exportId;
    const activeRequestId = active.requestId;
    setMp4ExportProgress((current) => {
      if (!current || current.requestId !== activeRequestId || (current.exportId && current.exportId !== progress.exportId)) {
        return current;
      }
      return replayMp4ExportUiProgress({ ...current, exportId: progress.exportId }, progress);
    });
    if (terminal) {
      retiredMp4ExportIdsRef.current.add(progress.exportId);
      while (retiredMp4ExportIdsRef.current.size > 64) {
        const oldest = retiredMp4ExportIdsRef.current.values().next().value as string | undefined;
        if (!oldest) break;
        retiredMp4ExportIdsRef.current.delete(oldest);
      }
      const latest = activeMp4ExportRef.current;
      if (latest?.requestId === activeRequestId && latest.exportId === progress.exportId) {
        activeMp4ExportRef.current = null;
      }
    }
  }), []);

