function ReplayDetail({
  model,
  settings,
  replayFolders,
  focusSeekRequest,
  onFocusSeekConsumed,
  onExport,
  onExportPresentationMp4,
  onSaveReplay,
  onDeleteReplay
}: {
  model: AtlasReplayViewModel;
  settings: UserSettings;
  replayFolders: ReplayFolder[];
  focusSeekRequest: { replayId: string; timeMs?: number; correctionEventId?: string; token: number } | null;
  onFocusSeekConsumed: () => void;
  onExport: (clipStartMs: number) => void;
  onExportPresentationMp4: (replayId: string, payload: ReplayPresentationRecordingPayload) => Promise<string>;
  onSaveReplay: (replay: ReplayRecord) => Promise<boolean>;
  onDeleteReplay: () => void;
}) {
  const analyticsMatch = model.match ? localToAnalytics(model.match) : null;
  const replayIntelligence = useMemo(() => buildReplayIntelligence(model.replay, model), [model]);
  const allScreenshots = useMemo(() => replayScreenshots(model), [model]);
  const screenshots = useMemo(() => trimmedReplayScreenshots(allScreenshots, model.replay.trim), [allScreenshots, model.replay.trim]);
  const [slideshowOpen, setSlideshowOpen] = useState(false);
  const [slideshowIndex, setSlideshowIndex] = useState(0);
  const [videoSeekMs, setVideoSeekMs] = useState<number | null>(null);
  const [evidenceOpen, setEvidenceOpen] = useState(false);
  const [focusedCorrectionEventId, setFocusedCorrectionEventId] = useState("");
  const [replayVideoCurrentMs, setReplayVideoCurrentMs] = useState(0);
  const [flagType, setFlagType] = useState<ReplayFlagType>("key-turn");
  const [flagCustomType, setFlagCustomType] = useState("");
  const [flagNote, setFlagNote] = useState("");
  const [customReplayFlagTypes, setCustomReplayFlagTypes] = useState<string[]>(() => settings.replayCustomFlagTypes ?? []);
  const [editingFlag, setEditingFlag] = useState<ReplayFlag | null>(null);
  const layers = useMemo(() => replayLayersFor(model.replay, settings.username), [model.replay, settings.username]);
  const [activeLayerId, setActiveLayerId] = useState(DEFAULT_REPLAY_LAYER_ID);
  const [visibleLayerIds, setVisibleLayerIds] = useState<Set<string>>(() => new Set(layers.map((layer) => layer.id)));
  const [addingLayer, setAddingLayer] = useState(false);
  const [layerStatus, setLayerStatus] = useState("");
  const [rawCaptureStatus, setRawCaptureStatus] = useState("");
  const [fileRevealStatus, setFileRevealStatus] = useState("");
  const [editingReplayTitle, setEditingReplayTitle] = useState(false);
  const [replayTitleDraft, setReplayTitleDraft] = useState(model.replay.title);
  const pendingLayerIdRef = useRef<string | null>(null);
  const activeLayer = layers.find((layer) => layer.id === activeLayerId) ?? layers[0];
  const layerVisible = (layerId: string | undefined) => visibleLayerIds.has(replayLayerId(layerId));
  const replayFlags = model.replay.flags ?? [];
  const replayAnnotations = model.replay.annotations ?? [];
  const replayVoiceNotes = model.replay.voiceNotes ?? [];
  const replayFlagsRef = useRef(replayFlags);
  const replayAnnotationsRef = useRef(replayAnnotations);
  const replayVoiceNotesRef = useRef(replayVoiceNotes);
  const visibleFlags = replayFlags.filter((flag) => layerVisible(flag.layerId));
  const visibleAnnotations = replayAnnotations.filter((annotation) => layerVisible(annotation.layerId));
  const visibleVoiceNotes = replayVoiceNotes.filter((note) => layerVisible(note.layerId));
  const trimSavings = replayTrimSavings(allScreenshots, screenshots);
  const [presentationMode, setPresentationMode] = useState(false);
  const [reviewMode, setReviewMode] = useState(false);
  const [reviewPreRollMs, setReviewPreRollMs] = useState(3000);
  const [reviewPostRollMs, setReviewPostRollMs] = useState(5000);
  const [activeReviewFlagId, setActiveReviewFlagId] = useState("");
  const [packDraft, setPackDraft] = useState(() => replayCoachingPackDraft(model.replay, settings.username));
  const reviewFlags = useMemo(() => [...visibleFlags]
    .filter((flag) => flag.targetType === "video-time" || flag.targetType === "frame" || flag.targetType === "turn")
    .sort((a, b) => replayFlagSortMs(a) - replayFlagSortMs(b)), [visibleFlags]);

  useEffect(() => {
    if (!focusSeekRequest || focusSeekRequest.replayId !== model.replay.id) return;
    if (typeof focusSeekRequest.timeMs === "number") setVideoSeekMs(focusSeekRequest.timeMs);
    if (focusSeekRequest.correctionEventId) {
      setEvidenceOpen(true);
      setFocusedCorrectionEventId(focusSeekRequest.correctionEventId);
    }
    onFocusSeekConsumed();
  }, [focusSeekRequest?.token, model.replay.id]);

  useEffect(() => {
    replayFlagsRef.current = replayFlags;
  }, [replayFlags]);

  useEffect(() => {
    replayAnnotationsRef.current = replayAnnotations;
  }, [replayAnnotations]);

  useEffect(() => {
    replayVoiceNotesRef.current = replayVoiceNotes;
  }, [replayVoiceNotes]);

  useEffect(() => {
    setSlideshowOpen(false);
    setSlideshowIndex(0);
    setReplayVideoCurrentMs(0);
    setEvidenceOpen(false);
    setFocusedCorrectionEventId("");
    pendingLayerIdRef.current = null;
    setAddingLayer(false);
    setLayerStatus("");
    setRawCaptureStatus("");
    setFileRevealStatus("");
    setEditingReplayTitle(false);
    setReplayTitleDraft(model.replay.title);
    setPresentationMode(false);
    setReviewMode(false);
    setActiveReviewFlagId("");
    setPackDraft(replayCoachingPackDraft(model.replay, settings.username));
    setActiveLayerId(layers.at(-1)?.id ?? DEFAULT_REPLAY_LAYER_ID);
    setVisibleLayerIds(new Set(layers.map((layer) => layer.id)));
  }, [model.replay.id, model.replay.title, settings.username]);

  useEffect(() => {
    const pendingLayerId = pendingLayerIdRef.current;
    if (pendingLayerId && layers.some((layer) => layer.id === pendingLayerId)) {
      pendingLayerIdRef.current = null;
      setActiveLayerId(pendingLayerId);
      setVisibleLayerIds((current) => new Set([...current, pendingLayerId]));
      const pendingLayer = layers.find((layer) => layer.id === pendingLayerId);
      setLayerStatus(`${pendingLayer?.name || "New layer"} selected.`);
      return;
    }
    if (!layers.some((layer) => layer.id === activeLayerId)) {
      setActiveLayerId(layers.at(-1)?.id ?? DEFAULT_REPLAY_LAYER_ID);
    }
    setVisibleLayerIds((current) => {
      const next = new Set(current);
      let changed = false;
      for (const layer of layers) {
        if (!next.has(layer.id)) {
          next.add(layer.id);
          changed = true;
        }
      }
      for (const layerId of [...next]) {
        if (!layers.some((layer) => layer.id === layerId)) {
          next.delete(layerId);
          changed = true;
        }
      }
      return changed ? next : current;
    });
  }, [activeLayerId, layers]);

  useEffect(() => {
    setCustomReplayFlagTypes(settings.replayCustomFlagTypes ?? []);
  }, [settings.replayCustomFlagTypes]);

  function selectReplayFlagType(value: string) {
    if (value.startsWith(CUSTOM_REPLAY_FLAG_PREFIX)) {
      setFlagType("custom");
      setFlagCustomType(value.slice(CUSTOM_REPLAY_FLAG_PREFIX.length));
      return;
    }
    setFlagType(value as ReplayFlagType);
    if (value !== "custom") {
      return;
    }
    setFlagCustomType("");
  }

  function rememberReplayCustomFlagType(label = flagCustomType): string {
    const normalized = normaliseCustomReplayFlagType(label);
    if (!normalized) {
      return "";
    }
    setCustomReplayFlagTypes((current) => {
      if (current.some((item) => item.toLowerCase() === normalized.toLowerCase())) {
        return current;
      }
      const next = [...current, normalized].slice(-24);
      void window.riftlite.saveSettings({ replayCustomFlagTypes: next }).catch(() => undefined);
      return next;
    });
    return normalized;
  }

  function openSlideshow(screenshot?: AtlasReplayViewModel["screenshots"][number]) {
    const index = screenshot
      ? allScreenshots.findIndex((item) => screenshotKey(item) === screenshotKey(screenshot))
      : trimIndexesForScreenshots(allScreenshots, model.replay.trim).start;
    setSlideshowIndex(index >= 0 ? index : 0);
    setSlideshowOpen(true);
  }

  function saveFlags(flags: ReplayFlag[]) {
    replayFlagsRef.current = flags;
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      flags
    });
  }

  function saveAnnotations(annotations: ReplayAnnotation[]) {
    replayAnnotationsRef.current = annotations;
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      annotations
    });
  }

  function saveVoiceNotes(voiceNotes: ReplayVoiceNote[]) {
    replayVoiceNotesRef.current = voiceNotes;
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      voiceNotes
    });
  }

  function addAnnotation(annotation: ReplayAnnotation) {
    saveAnnotations([...replayAnnotationsRef.current, { ...annotation, layerId: annotation.layerId ?? activeLayerId }]);
  }

  function removeAnnotation(id: string) {
    saveAnnotations(replayAnnotations.filter((annotation) => annotation.id !== id));
  }

  function removeAnnotations(ids: string[]) {
    const deleteIds = new Set(ids);
    saveAnnotations(replayAnnotationsRef.current.filter((annotation) => !deleteIds.has(annotation.id)));
  }

  async function exportReplayFlagsTextFile() {
    setLayerStatus("Exporting replay timestamps...");
    try {
      const exportedPath = await window.riftlite.exportReplayFlagsText(model.replay.id);
      setLayerStatus(exportedPath ? `Exported replay timestamps to ${exportedPath}` : "");
    } catch (error) {
      setLayerStatus(rendererErrorMessage(error, "Replay timestamp export failed."));
    }
  }

  function replayAnnotationBelongsToFlag(annotation: ReplayAnnotation, flag: ReplayFlag, notes: ReplayVoiceNote[]): boolean {
    const clipIds = new Set(notes.filter((note) => note.flagId === flag.id).map((note) => note.id));
    if (annotation.clipId && clipIds.has(annotation.clipId)) {
      return true;
    }
    if (flag.targetType === "frame") {
      return annotation.targetType === "frame" && annotation.targetId === flag.targetId;
    }
    if (flag.targetType === "video-time") {
      if (annotation.targetType !== "video-time") {
        return false;
      }
      if (annotation.targetId === flag.targetId) {
        return true;
      }
      if (typeof annotation.timeMs === "number" && typeof flag.timeMs === "number") {
        return Math.abs(annotation.timeMs - flag.timeMs) <= 1500;
      }
    }
    return false;
  }

  function addReplayFlag(
    targetType: ReplayFlag["targetType"],
    targetId: string,
    targetLabel: string,
    capturedAt: string,
    fallbackLabel = "Key moment"
  ) {
    const type = flagType;
    const customType = type === "custom" ? rememberReplayCustomFlagType(flagCustomType) : "";
    const label = type === "custom" ? customType || fallbackLabel : REPLAY_FLAG_TYPES.find((item) => item.value === type)?.label || fallbackLabel;
    const exists = replayFlags.some((flag) =>
      flag.targetType === targetType &&
      flag.targetId === targetId &&
      replayLayerId(flag.layerId) === activeLayerId &&
      flag.label.toLowerCase() === label.toLowerCase()
    );
    if (exists) {
      return;
    }
    saveFlags([
      ...replayFlags,
      {
        id: crypto.randomUUID(),
        targetType,
        targetId,
        targetLabel,
        type,
        layerId: activeLayerId,
        ...(customType ? { customType } : {}),
        label,
        note: flagNote.trim(),
        capturedAt,
        createdAt: new Date().toISOString()
      }
    ]);
    setFlagNote("");
  }

  function removeReplayFlag(id: string) {
    const flag = replayFlagsRef.current.find((item) => item.id === id);
    if (!flag) {
      return;
    }
    const nextFlags = replayFlagsRef.current.filter((item) => item.id !== id);
    const nextVoiceNotes = replayVoiceNotesRef.current.filter((note) => note.flagId !== id);
    const nextAnnotations = replayAnnotationsRef.current.filter((annotation) =>
      !replayAnnotationBelongsToFlag(annotation, flag, replayVoiceNotesRef.current)
    );
    replayFlagsRef.current = nextFlags;
    replayVoiceNotesRef.current = nextVoiceNotes;
    replayAnnotationsRef.current = nextAnnotations;
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      flags: nextFlags,
      annotations: nextAnnotations,
      voiceNotes: nextVoiceNotes
    });
    setEditingFlag(null);
  }

  function updateReplayFlag(nextFlag: ReplayFlag) {
    saveFlags(replayFlags.map((flag) => flag.id === nextFlag.id ? nextFlag : flag));
    setEditingFlag(null);
  }

  function saveTimelineVoiceNote(flag: ReplayFlag, voiceNote: ReplayVoiceNote) {
    const currentFlags = replayFlagsRef.current;
    const currentVoiceNotes = replayVoiceNotesRef.current;
    const flags = currentFlags.some((item) => item.id === flag.id) ? currentFlags : [...currentFlags, flag];
    const voiceNotes = [
      ...currentVoiceNotes.filter((note) => !(note.flagId === voiceNote.flagId && replayLayerId(note.layerId) === replayLayerId(voiceNote.layerId))),
      voiceNote
    ];
    replayFlagsRef.current = flags;
    replayVoiceNotesRef.current = voiceNotes;
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      flags,
      annotations: replayAnnotationsRef.current,
      voiceNotes
    });
  }

  function deleteReplayVoiceNote(flagId: string, layerId: string) {
    const notesToDelete = replayVoiceNotesRef.current.filter((note) =>
      note.flagId === flagId && replayLayerId(note.layerId) === layerId
    );
    const clipIds = new Set(notesToDelete.map((note) => note.id));
    const voiceNotes = replayVoiceNotesRef.current.filter((note) =>
      !(note.flagId === flagId && replayLayerId(note.layerId) === layerId)
    );
    const annotations = replayAnnotationsRef.current.filter((annotation) =>
      !annotation.clipId || !clipIds.has(annotation.clipId)
    );
    replayVoiceNotesRef.current = voiceNotes;
    replayAnnotationsRef.current = annotations;
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      annotations,
      voiceNotes
    });
  }

  function addVideoTimeFlag(timeMs: number) {
    const video = model.replay.video;
    if (!video) {
      return;
    }
    const type = flagType;
    const customType = type === "custom" ? rememberReplayCustomFlagType(flagCustomType) : "";
    const label = type === "custom" ? customType || "Video moment" : REPLAY_FLAG_TYPES.find((item) => item.value === type)?.label || "Video moment";
    const targetId = `${video.path || video.url}:${Math.round(timeMs)}`;
    const exists = replayFlags.some((flag) =>
      flag.targetType === "video-time" &&
      flag.targetId === targetId &&
      replayLayerId(flag.layerId) === activeLayerId &&
      flag.label.toLowerCase() === label.toLowerCase()
    );
    if (exists) {
      return;
    }
    saveFlags([
      ...replayFlags,
      {
        id: crypto.randomUUID(),
        targetType: "video-time",
        targetId,
        targetLabel: `Video ${formatDuration(timeMs)}`,
        type,
        layerId: activeLayerId,
        ...(customType ? { customType } : {}),
        label,
        note: flagNote.trim(),
        capturedAt: replayVideoCapturedAt(video, timeMs),
        createdAt: new Date().toISOString(),
        timeMs
      }
    ]);
    setFlagNote("");
  }

  async function saveVideoKeyframe(dataUrl: string, timeMs: number): Promise<void> {
    const video = model.replay.video;
    if (!video) {
      return;
    }
    const label = `Video keyframe ${formatDuration(timeMs)}`;
    const frame = await window.riftlite.saveReplayVideoKeyframe({
      replayId: model.replay.id,
      dataUrl,
      label,
      capturedAt: replayVideoCapturedAt(video, timeMs)
    });
    await onSaveReplay({
      ...model.replay,
      visualFrames: [...(model.replay.visualFrames ?? []), frame]
    });
  }

  function openFlag(flag: ReplayFlag) {
    if (flag.targetType === "frame") {
      const screenshot = allScreenshots.find((item) => replayFrameTargetId(item) === flag.targetId);
      if (screenshot) {
        openSlideshow(screenshot);
      }
    } else if (flag.targetType === "video-time" && typeof flag.timeMs === "number") {
      setVideoSeekMs(flag.timeMs);
    }
  }

  function openReviewFlag(flag: ReplayFlag) {
    setActiveReviewFlagId(flag.id);
    if (flag.targetType === "video-time" && typeof flag.timeMs === "number") {
      setVideoSeekMs(Math.max(0, flag.timeMs - reviewPreRollMs));
      return;
    }
    openFlag(flag);
  }

  function jumpReviewFlag(direction: "previous" | "next") {
    if (!reviewFlags.length) {
      return;
    }
    const currentIndex = Math.max(0, reviewFlags.findIndex((flag) => flag.id === activeReviewFlagId));
    const nextIndex = direction === "next"
      ? Math.min(reviewFlags.length - 1, currentIndex + (activeReviewFlagId ? 1 : 0))
      : Math.max(0, currentIndex - 1);
    openReviewFlag(reviewFlags[nextIndex]);
  }

  useEffect(() => {
    if (!reviewMode || !activeReviewFlagId) {
      return;
    }
    const active = reviewFlags.find((flag) => flag.id === activeReviewFlagId);
    if (!active || active.targetType !== "video-time" || typeof active.timeMs !== "number") {
      return;
    }
    if (replayVideoCurrentMs >= active.timeMs + reviewPostRollMs) {
      const index = reviewFlags.findIndex((flag) => flag.id === active.id);
      const next = reviewFlags[index + 1];
      if (next) {
        openReviewFlag(next);
      } else {
        setReviewMode(false);
      }
    }
  }, [activeReviewFlagId, replayVideoCurrentMs, reviewFlags, reviewMode, reviewPostRollMs]);

  function saveReplayTrim(trim: ReplayTrimRange) {
    void onSaveReplay({
      ...model.replay,
      trim
    });
  }

  function clearReplayTrim() {
    const nextReplay = { ...model.replay };
    delete nextReplay.trim;
    void onSaveReplay(nextReplay);
  }

  function saveCoachingPackMetadata() {
    void onSaveReplay({
      ...model.replay,
      schemaVersion: 5,
      coachingPack: {
        ...packDraft,
        updatedAt: new Date().toISOString()
      }
    });
  }

  async function addTeachingLayer() {
    if (addingLayer) {
      return;
    }
    const presetNames = ["Player review", "Coach review", "Follow-up"];
    const name = uniqueReplayLayerName(layers, presetNames[Math.min(layers.length, presetNames.length - 1)]);
    const nextLayer: ReplayTeachingLayer = {
      id: crypto.randomUUID(),
      name,
      author: settings.username || (name.includes("Coach") ? "Coach" : "Player"),
      color: REPLAY_ANNOTATION_COLORS[(layers.length + 1) % REPLAY_ANNOTATION_COLORS.length],
      createdAt: new Date().toISOString()
    };
    pendingLayerIdRef.current = nextLayer.id;
    setAddingLayer(true);
    setLayerStatus(`Adding ${nextLayer.name}...`);
    setVisibleLayerIds((current) => new Set([...current, nextLayer.id]));
    try {
      await onSaveReplay({
        ...model.replay,
        schemaVersion: 5,
        layers: [...layers, nextLayer]
      });
      setActiveLayerId(nextLayer.id);
      setVisibleLayerIds((current) => new Set([...current, nextLayer.id]));
      setLayerStatus(`${nextLayer.name} selected.`);
    } catch {
      pendingLayerIdRef.current = null;
      setVisibleLayerIds((current) => {
        const next = new Set(current);
        next.delete(nextLayer.id);
        return next;
      });
      setLayerStatus("Layer could not be added.");
    } finally {
      setAddingLayer(false);
    }
  }

  async function uploadRawCapture() {
    setRawCaptureStatus("Uploading raw capture...");
    try {
      const result = await window.riftlite.uploadRawCaptureToRiftLite(model.replay.id, settings.rawCapture.visibility);
      const updatedReplays = await window.riftlite.getReplays();
      const saved = updatedReplays.find((replay) => replay.id === model.replay.id) ?? null;
      if (!saved) {
        setRawCaptureStatus("No raw capture is attached to this replay.");
        return;
      }
      await onSaveReplay(saved);
      setRawCaptureStatus(`RiftLite replay uploaded: ${result.url}`);
    } catch (error) {
      setRawCaptureStatus(rendererErrorMessage(error, "Raw capture upload failed."));
    }
  }

  async function shareRawCaptureToDiscord() {
    const activeHubIds = new Set(settings.activeHubs.map((hub) => hub.id));
    const hubIds = activeDiscordReplayHubIds(settings).filter((hubId) => activeHubIds.has(hubId));
    const hubNames = settings.activeHubs
      .filter((hub) => hubIds.includes(hub.id))
      .map((hub) => `${hub.name} (${hub.id})`);
    if (!hubIds.length) {
      setRawCaptureStatus("Select a Discord replay destination from the Account tab first.");
      return;
    }
    const destinations = hubNames.length ? hubNames.join(", ") : hubIds.join(", ");
    if (!window.confirm(
      `Make this replay Unlisted and post its link to ${destinations}? Anyone with the Discord link will be able to watch it.`
    )) {
      return;
    }
    setRawCaptureStatus("Sharing replay to Discord...");
    try {
      const result = await window.riftlite.shareRawCaptureToDiscord(model.replay.id);
      const updatedReplays = await window.riftlite.getReplays();
      const saved = updatedReplays.find((replay) => replay.id === model.replay.id) ?? null;
      if (saved) await onSaveReplay(saved);
      setRawCaptureStatus(result.status === "shared"
        ? "Replay posted to Discord. Its visibility is now Unlisted."
        : result.error || "One or more Discord destinations could not receive the replay.");
    } catch (error) {
      setRawCaptureStatus(rendererErrorMessage(error, "Discord replay share failed."));
    }
  }

  function toggleLayer(layerId: string) {
    setVisibleLayerIds((current) => {
      const next = new Set(current);
      if (next.has(layerId)) {
        next.delete(layerId);
      } else {
        next.add(layerId);
      }
      if (!next.size) {
        next.add(layerId);
      }
      return next;
    });
  }

  function selectActiveLayer(layerId: string) {
    setActiveLayerId(layerId);
    setVisibleLayerIds((current) => new Set([...current, layerId]));
  }

  async function revealLocalReplayFile(preferredKind?: ReplayLocalAssetKind) {
    setFileRevealStatus("Finding the local replay file...");
    try {
      const result = await window.riftlite.revealReplayFile(model.replay.id, preferredKind);
      const label = result.kind === "video"
        ? "Replay video"
        : result.kind === "raw-capture"
          ? "Web Replay source"
          : result.kind === "replay-bundle"
            ? "Replay bundle"
            : "Replay frame";
      setFileRevealStatus(`${label} selected in its folder.`);
    } catch (error) {
      setFileRevealStatus(rendererErrorMessage(error, "No local replay file could be found."));
    }
  }

  async function saveReplayTitle() {
    const title = replayTitleDraft.trim().replace(/\s+/g, " ").slice(0, 160);
    if (!title) {
      return;
    }
    const saved = await onSaveReplay({ ...model.replay, title });
    if (!saved) {
      return;
    }
    setReplayTitleDraft(title);
    setEditingReplayTitle(false);
  }

  async function moveReplayToFolder(folderId: string) {
    await onSaveReplay({
      ...model.replay,
      folderId: replayFolders.some((folder) => folder.id === folderId) ? folderId : undefined
    });
  }

  return (
    <div className={`replay-detail-stack ${presentationMode ? "presentation-mode" : ""}`}>
      <section className="rail-card replay-hero">
        <div>
          <span>{model.platformLabel} replay</span>
          {editingReplayTitle ? (
            <div className="replay-title-editor">
              <input
                autoFocus
                value={replayTitleDraft}
                maxLength={160}
                onChange={(event) => setReplayTitleDraft(event.target.value)}
                onKeyDown={(event) => {
                  if (event.key === "Enter") {
                    void saveReplayTitle();
                  }
                  if (event.key === "Escape") {
                    setReplayTitleDraft(model.replay.title);
                    setEditingReplayTitle(false);
                  }
                }}
              />
              <button type="button" className="secondary" disabled={!replayTitleDraft.trim()} onClick={() => void saveReplayTitle()}><Save size={14} /> Save</button>
              <button type="button" className="secondary" onClick={() => { setReplayTitleDraft(model.replay.title); setEditingReplayTitle(false); }}><X size={14} /></button>
            </div>
          ) : (
            <div className="replay-title-row">
              <h2>{model.title}</h2>
              <button type="button" className="secondary compact" onClick={() => setEditingReplayTitle(true)}>Rename</button>
            </div>
          )}
          <p>{model.players.me || "Player"} vs {model.players.opponent || "Opponent"} - {new Date(model.capturedAt).toLocaleString()}</p>
          <label className="replay-folder-assignment">
            <FolderOpen size={13} /> Folder
            <select value={model.replay.folderId ?? ""} onChange={(event) => void moveReplayToFolder(event.target.value)}>
              <option value="">Unfiled</option>
              {replayFolders.map((folder) => <option value={folder.id} key={folder.id}>{folder.name}</option>)}
            </select>
          </label>
          {fileRevealStatus ? <p className="replay-local-file-status" role="status">{fileRevealStatus}</p> : null}
        </div>
        <div className="replay-hero-actions">
          <div className="replay-status-cluster">
            <strong>{model.resultLabel || "Captured"}</strong>
            <span>{model.scoreLabel}</span>
          </div>
          <button
            type="button"
            className={`secondary replay-favourite-detail${model.replay.favourite ? " active" : ""}`}
            onClick={() => void onSaveReplay({ ...model.replay, favourite: !model.replay.favourite })}
          >
            <Star size={16} fill={model.replay.favourite ? "currentColor" : "none"} />
            {model.replay.favourite ? "Favourited" : "Favourite"}
          </button>
          <button
            type="button"
            className="secondary"
            disabled={!allScreenshots.length}
            onClick={() => openSlideshow()}
            title={allScreenshots.length ? "Open visual replay and trim timeline" : "No replay frames captured yet"}
          >
            <Images size={16} /> Visual replay
          </button>
          <button type="button" className="secondary" onClick={() => onExport(replayVideoCurrentMs)}>
            <ExternalLink size={16} /> Export
          </button>
          <button
            type="button"
            className="secondary"
            onClick={() => void revealLocalReplayFile()}
            title="Select this replay's video, Web Replay source, bundle, or first local frame in your file manager"
          >
            <FolderOpen size={16} /> Show in folder
          </button>
          <button type="button" className="secondary" onClick={() => setPresentationMode((value) => !value)}>
            <Maximize2 size={16} /> {presentationMode ? "Exit presentation" : "Presentation"}
          </button>
          <button type="button" className="secondary danger" onClick={onDeleteReplay}>
            Delete replay
          </button>
        </div>
      </section>

      {model.replay.video ? (
        <ReplayVideoPlayer
          key={model.replay.id}
          replayId={model.replay.id}
          video={model.replay.video}
          flags={visibleFlags.filter((flag) => flag.targetType === "video-time")}
          annotations={visibleAnnotations.filter((annotation) => annotation.targetType === "video-time")}
          voiceNotes={visibleVoiceNotes}
          intelligenceEvents={replayIntelligence.events}
          seekToMs={videoSeekMs}
          onSeekHandled={() => setVideoSeekMs(null)}
          onTimeChange={setReplayVideoCurrentMs}
          flagType={flagType}
          flagCustomType={flagCustomType}
          flagNote={flagNote}
          customFlagTypes={customReplayFlagTypes}
          onFlagTypeSelect={selectReplayFlagType}
          onFlagCustomTypeChange={setFlagCustomType}
          onFlagNoteChange={setFlagNote}
          onRememberCustomType={() => {
            const saved = rememberReplayCustomFlagType();
            if (saved) {
              setFlagType("custom");
              setFlagCustomType(saved);
            }
          }}
          onFlagTime={addVideoTimeFlag}
          onEditFlag={setEditingFlag}
          onSaveKeyframe={saveVideoKeyframe}
          activeLayerId={activeLayerId}
          microphoneDeviceId={settings.microphoneDeviceId}
          onSaveTimelineVoiceNote={saveTimelineVoiceNote}
          onAddAnnotation={addAnnotation}
          onRemoveAnnotation={removeAnnotation}
          onRemoveAnnotations={removeAnnotations}
          onClip={(timeMs) => onExport(timeMs)}
          onExportPresentationMp4={onExportPresentationMp4}
        />
      ) : null}

      <div className="replay-metric-grid">
        <Metric label="Turns" value={String(model.turns.length)} />
        <Metric label="Events" value={String(model.events.length)} />
        <Metric label="Evidence" value={String(model.evidenceCount)} />
        <Metric label="Board cards" value={String(replaySnapshotCardCount(model.replay))} />
        <Metric label="Replay frames" value={trimSavings} />
        <Metric label="Video" value={model.replay.video ? formatBytes(model.replay.video.sizeBytes) : "Off"} />
      </div>

      <details className="replay-evidence-drawer" open={evidenceOpen} onToggle={(event) => setEvidenceOpen(event.currentTarget.open)}>
        <summary><Activity size={16} /><span><strong>Evidence and corrections</strong><small>Inspect the event trail behind Insights or correct reconstructed data.</small></span><ChevronDown size={16} /></summary>
        <ReplayIntelligencePanel
          model={model}
          result={replayIntelligence}
          focusCorrectionEventId={focusedCorrectionEventId}
          onFocusCorrectionHandled={() => setFocusedCorrectionEventId("")}
          onSeek={(timeMs) => setVideoSeekMs(timeMs)}
          onSaveReplay={onSaveReplay}
        />
      </details>

      <ReplayHealthPanel
        model={model}
        screenshots={screenshots}
        layers={layers}
        flags={replayFlags}
        annotations={replayAnnotations}
        voiceNotes={replayVoiceNotes}
      />

      {RIFTLITE_WEB_REPLAY_FEATURE_VISIBLE ? (
        <ReplayRawCapturePanel
          replay={model.replay}
          settings={settings}
          status={rawCaptureStatus}
          onUpload={() => void uploadRawCapture()}
          onShareDiscord={() => void shareRawCaptureToDiscord()}
          onRevealSource={() => void revealLocalReplayFile("raw-capture")}
        />
      ) : null}

      <section className="rail-card replay-pack-panel">
        <header>
          <div>
            <h2>Coaching pack</h2>
            <span>These details travel with exported .riftreplay files.</span>
          </div>
          <button type="button" className="secondary" onClick={saveCoachingPackMetadata}>
            <Save size={14} /> Save details
          </button>
        </header>
        <div className="replay-pack-grid">
          <label>
            Title
            <input value={packDraft.title} onChange={(event) => setPackDraft({ ...packDraft, title: event.target.value })} />
          </label>
          <label>
            Author
            <input value={packDraft.author} onChange={(event) => setPackDraft({ ...packDraft, author: event.target.value })} />
          </label>
          <label>
            Purpose
            <input value={packDraft.purpose} onChange={(event) => setPackDraft({ ...packDraft, purpose: event.target.value })} />
          </label>
          <label>
            Summary
            <textarea value={packDraft.summary} onChange={(event) => setPackDraft({ ...packDraft, summary: event.target.value })} placeholder="What should the reviewer focus on?" />
          </label>
        </div>
      </section>

      <ReplayLayerPanel
        layers={layers}
        activeLayerId={activeLayerId}
        visibleLayerIds={visibleLayerIds}
        addingLayer={addingLayer}
        status={layerStatus}
        onActiveLayerChange={selectActiveLayer}
        onToggleLayer={toggleLayer}
        onAddLayer={addTeachingLayer}
      />

      <section className="rail-card replay-review-toolbar">
        <div>
          <h2>Review mode</h2>
          <span>{reviewFlags.length ? `${reviewFlags.length} flagged moment${reviewFlags.length === 1 ? "" : "s"} ready` : "Add flags to build a coaching route through this replay."}</span>
        </div>
        <div className="replay-review-controls">
          <button type="button" className="secondary" disabled={!reviewFlags.length} onClick={() => {
            setReviewMode((value) => !value);
            if (!reviewMode) {
              openReviewFlag(reviewFlags[0]);
            }
          }}>
            <Play size={14} /> {reviewMode ? "Stop review" : "Start review"}
          </button>
          <button type="button" className="secondary" disabled={!reviewFlags.length} onClick={() => jumpReviewFlag("previous")}>Previous flag</button>
          <button type="button" className="secondary" disabled={!reviewFlags.length} onClick={() => jumpReviewFlag("next")}>Next flag</button>
          <label>
            Pre-roll
            <select value={reviewPreRollMs} onChange={(event) => setReviewPreRollMs(Number(event.target.value))}>
              <option value={0}>0s</option>
              <option value={3000}>3s</option>
              <option value={5000}>5s</option>
              <option value={10000}>10s</option>
            </select>
          </label>
          <label>
            Post-roll
            <select value={reviewPostRollMs} onChange={(event) => setReviewPostRollMs(Number(event.target.value))}>
              <option value={3000}>3s</option>
              <option value={5000}>5s</option>
              <option value={10000}>10s</option>
              <option value={15000}>15s</option>
            </select>
          </label>
        </div>
      </section>

      {reviewFlags.length ? (
        <section className="rail-card replay-flagged-moments">
          <header>
            <div>
              <h2>Flagged moments</h2>
              <span>Jump straight to the teaching points in this replay.</span>
            </div>
          </header>
          <div className="replay-flagged-grid">
            {reviewFlags.map((flag) => (
              <button
                type="button"
                key={flag.id}
                data-active={activeReviewFlagId === flag.id}
                onClick={() => openReviewFlag(flag)}
              >
                <span>{flag.timeMs != null ? formatDuration(flag.timeMs) : new Date(flag.capturedAt).toLocaleTimeString()}</span>
                <strong>{replayFlagTypeLabel(flag)}</strong>
                <em>{flag.targetLabel}</em>
                {flag.note ? <small>{flag.note}</small> : null}
              </button>
            ))}
          </div>
        </section>
      ) : null}

      <ReplayFlagPanel
        flags={visibleFlags}
        flagType={flagType}
        flagCustomType={flagCustomType}
        flagNote={flagNote}
        customFlagTypes={customReplayFlagTypes}
        replay={model.replay}
        onFlagTypeSelect={selectReplayFlagType}
        onFlagCustomTypeChange={setFlagCustomType}
        onFlagNoteChange={setFlagNote}
        onAddReplayFlag={() => addReplayFlag("replay", model.replay.id, model.title, model.capturedAt, "Replay note")}
        onRememberCustomType={() => {
          const saved = rememberReplayCustomFlagType();
          if (saved) {
            setFlagType("custom");
            setFlagCustomType(saved);
          }
        }}
        onExportFlagsText={() => void exportReplayFlagsTextFile()}
        onOpenFlag={(flag) => {
          openFlag(flag);
          setEditingFlag(flag);
        }}
        onRemoveFlag={removeReplayFlag}
      />

      {DECK_TRACKER_FEATURE_ENABLED ? <ReplayDeckTrackerPanel replay={model.replay} currentTimeMs={replayVideoCurrentMs} /> : null}
      <ReplayBattlefields model={model} />
      {analyticsMatch ? <MatchDetailPanel match={analyticsMatch} showFlags={false} /> : null}
      {slideshowOpen ? (
        <ReplaySlideshow
          title={model.title}
          players={`${model.players.me || "Player"} vs ${model.players.opponent || "Opponent"}`}
          screenshots={allScreenshots}
          flags={visibleFlags}
          annotations={visibleAnnotations.filter((annotation) => annotation.targetType === "frame")}
          voiceNotes={visibleVoiceNotes}
          initialIndex={slideshowIndex}
          trim={model.replay.trim}
          onFlagFrame={(screenshot) => addReplayFlag("frame", replayFrameTargetId(screenshot), screenshot.label, screenshot.capturedAt, "Key frame")}
          onEditFlag={setEditingFlag}
          activeLayerId={activeLayerId}
          onAddAnnotation={addAnnotation}
          onRemoveAnnotation={removeAnnotation}
          onRemoveAnnotations={removeAnnotations}
          onSaveTrim={saveReplayTrim}
          onClearTrim={clearReplayTrim}
          onClose={() => setSlideshowOpen(false)}
        />
      ) : null}
      {editingFlag ? (
        <ReplayFlagEditor
          flag={editingFlag}
          voiceNotes={visibleVoiceNotes.filter((note) => note.flagId === editingFlag.id)}
          activeLayerId={activeLayerId}
          activeLayerName={activeLayer?.name ?? "Active layer"}
          microphoneDeviceId={settings.microphoneDeviceId}
          onSave={updateReplayFlag}
          onDelete={() => removeReplayFlag(editingFlag.id)}
          onSaveVoiceNote={(voiceNote) => saveVoiceNotes([
            ...replayVoiceNotes.filter((note) => !(note.flagId === editingFlag.id && replayLayerId(note.layerId) === activeLayerId)),
            voiceNote
          ])}
          onDeleteVoiceNote={() => deleteReplayVoiceNote(editingFlag.id, activeLayerId)}
          onCancel={() => setEditingFlag(null)}
        />
      ) : null}
    </div>
  );
}

type ReplayIntelligenceTab = "overview" | "timeline" | "cards";

function ReplayIntelligencePanel({
  model,
  result,
  focusCorrectionEventId,
  onFocusCorrectionHandled,
  onSeek,
  onSaveReplay
}: {
  model: AtlasReplayViewModel;
  result: ReplayIntelligenceResult;
  focusCorrectionEventId: string;
  onFocusCorrectionHandled: () => void;
  onSeek: (timeMs: number) => void;
  onSaveReplay: (replay: ReplayRecord) => Promise<boolean>;
}) {
  const [tab, setTab] = useState<ReplayIntelligenceTab>("overview");
  const [search, setSearch] = useState("");
  const [eventType, setEventType] = useState("all");
  const [side, setSide] = useState("all");
  const [confidence, setConfidence] = useState("all");
  const [selectedCard, setSelectedCard] = useState("");
  const [editingEvent, setEditingEvent] = useState<ReplayIntelligenceEvent | null>(null);
  const [status, setStatus] = useState("");
  const [saving, setSaving] = useState(false);
  const summary = result.summary;
  const eventTypes = useMemo(() => [...new Set(result.events.map((event) => event.type))].sort(), [result.events]);
  const filteredEvents = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return result.events.filter((event) => {
      if (eventType !== "all" && event.type !== eventType) return false;
      if (side !== "all" && event.side !== side) return false;
      if (confidence !== "all" && event.confidence !== confidence) return false;
      if (selectedCard && replayIntelligenceCardKey(event.cardId || event.cardName) !== selectedCard) return false;
      if (!needle) return true;
      return [event.id, event.text, event.cardName, event.cardId, event.battlefield, event.destination, event.fromZone, event.toZone, event.turnLabel, event.correctionNote]
        .filter(Boolean)
        .join(" ")
        .toLowerCase()
        .includes(needle);
    });
  }, [confidence, eventType, result.events, search, selectedCard, side]);

  useEffect(() => {
    setTab("overview");
    setSearch("");
    setEventType("all");
    setSide("all");
    setConfidence("all");
    setSelectedCard("");
    setEditingEvent(null);
    setStatus("");
  }, [model.replay.id]);

  useEffect(() => {
    if (!focusCorrectionEventId) return;
    setTab("timeline");
    setEventType("all");
    setSide("all");
    setConfidence("all");
    setSelectedCard("");
    setSearch(focusCorrectionEventId);
    const focusedEvent = result.events.find((event) => event.id === focusCorrectionEventId);
    if (focusedEvent) {
      setEditingEvent(focusedEvent);
      setStatus("Opened the evidence supporting this insight.");
    } else {
      setStatus("This insight came from retained raw capture evidence. The source is preserved, but it has no editable timeline row.");
    }
    onFocusCorrectionHandled();
  }, [focusCorrectionEventId, result.events]);

  async function saveIntelligence(corrections: ReplayIntelligenceCorrection[], message: string) {
    setSaving(true);
    setStatus("Saving Replay Intelligence locally...");
    try {
      const nextReplay = replayWithIntelligence({
        ...model.replay,
        schemaVersion: 5,
        intelligence: { ...summary, corrections }
      }, model.match, corrections);
      const saved = await onSaveReplay(nextReplay);
      setStatus(saved ? message : "Replay Intelligence could not be saved.");
      if (saved) setEditingEvent(null);
    } finally {
      setSaving(false);
    }
  }

  function openCardJourney(cardKey: string) {
    setSelectedCard(cardKey);
    setEventType("all");
    setSearch("");
    setTab("timeline");
  }

  const coverageTotal = Math.max(1, summary.coverage.totalEvents);
  return (
    <section className="rail-card replay-intelligence-panel" data-grade={summary.coverage.grade}>
      <header className="replay-intelligence-header">
        <div>
          <span className="replay-intelligence-kicker"><Activity size={14} /> Insight evidence</span>
          <h2>Replay evidence</h2>
          <p>The event trail behind your Insights. Audit what RiftLite reconstructed, follow card journeys, or correct the retained evidence layer.</p>
        </div>
        <div className="replay-intelligence-grade">
          <strong>{summary.coverage.grade}</strong>
          <span>evidence coverage</span>
        </div>
      </header>

      <div className="replay-intelligence-tabs" role="tablist" aria-label="Replay evidence views">
        {([
          ["overview", "Game story"],
          ["timeline", `Timeline ${result.events.length}`],
          ["cards", `Card journeys ${summary.cardJourneys.length}`]
        ] as Array<[ReplayIntelligenceTab, string]>).map(([value, label]) => (
          <button type="button" role="tab" aria-selected={tab === value} data-active={tab === value} key={value} onClick={() => setTab(value)}>{label}</button>
        ))}
        <button type="button" className="replay-intelligence-save" disabled={saving} onClick={() => void saveIntelligence(summary.corrections, "Replay evidence saved locally.")}>
          <Save size={13} /> {saving ? "Saving..." : "Save evidence"}
        </button>
      </div>

      {tab === "overview" ? (
        <div className="replay-intelligence-overview">
          <div className="replay-intelligence-stat-grid">
            <ReplayIntelligenceStat label="Games" value={summary.stats.games} />
            <ReplayIntelligenceStat label="Turns" value={summary.stats.turns} />
            <ReplayIntelligenceStat label="Card actions" value={summary.stats.cardActions} />
            <ReplayIntelligenceStat label="Scoring" value={summary.stats.scoringEvents} />
            <ReplayIntelligenceStat label="Combat" value={summary.stats.combats} />
            <ReplayIntelligenceStat label="Corrections" value={summary.corrections.length} />
          </div>

          <div className="replay-intelligence-overview-grid">
            <article className="replay-intelligence-story">
              <h3><History size={16} /> Game story</h3>
              <ol>
                {summary.story.map((line, index) => <li key={`${index}:${line}`}>{line}</li>)}
              </ol>
            </article>
            <article className="replay-intelligence-coverage">
              <h3><Activity size={16} /> Evidence mix</h3>
              {(["confirmed", "reconstructed", "inferred", "manual"] as ReplayIntelligenceConfidence[]).map((value) => {
                const count = summary.coverage[value];
                return (
                  <div key={value}>
                    <span>{replayIntelligenceConfidenceLabel(value)} <strong>{count}</strong></span>
                    <i><b data-confidence={value} style={{ width: `${(count / coverageTotal) * 100}%` }} /></i>
                  </div>
                );
              })}
              <small>{summary.coverage.cardEvents} card events · {summary.coverage.scoreEvents} score events · {summary.coverage.hasVideo ? "video linked" : "no video"}</small>
            </article>
          </div>

          <div className="replay-intelligence-moments">
            <h3><Lightbulb size={16} /> Review moments</h3>
            {summary.moments.length ? (
              <div>
                {summary.moments.map((moment) => (
                  <button
                    type="button"
                    key={moment.id}
                    data-kind={moment.kind}
                    onClick={() => {
                      if (typeof moment.videoTimeMs === "number") onSeek(moment.videoTimeMs);
                      setSearch(moment.eventId ?? "");
                      setTab("timeline");
                    }}
                  >
                    <span>{moment.kind.replace("-", " ")} · {replayIntelligenceConfidenceLabel(moment.confidence)}</span>
                    <strong>{moment.title}</strong>
                    <p>{moment.body}</p>
                    {typeof moment.videoTimeMs === "number" ? <small><Play size={11} /> {formatDuration(moment.videoTimeMs)}</small> : null}
                  </button>
                ))}
              </div>
            ) : <p className="muted">More structured events are needed before RiftLite can identify useful review moments.</p>}
          </div>

          {summary.limitations.length ? (
            <details className="replay-intelligence-limitations">
              <summary>What this replay cannot prove</summary>
              <ul>{summary.limitations.map((line) => <li key={line}>{line}</li>)}</ul>
            </details>
          ) : null}
        </div>
      ) : null}

      {tab === "timeline" ? (
        <div className="replay-intelligence-timeline">
          <div className="replay-intelligence-filters">
            <label className="replay-intelligence-search">Search<input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Card, battlefield, action, turn..." /></label>
            <label>Event<select value={eventType} onChange={(event) => setEventType(event.target.value)}><option value="all">All events</option>{eventTypes.map((value) => <option value={value} key={value}>{value.replace("-", " ")}</option>)}</select></label>
            <label>Side<select value={side} onChange={(event) => setSide(event.target.value)}><option value="all">Both players</option><option value="me">Player</option><option value="opponent">Opponent</option><option value="system">System</option><option value="unknown">Unknown</option></select></label>
            <label>Evidence<select value={confidence} onChange={(event) => setConfidence(event.target.value)}><option value="all">All confidence</option><option value="confirmed">Confirmed</option><option value="reconstructed">Reconstructed</option><option value="inferred">Inferred</option><option value="manual">Manual</option></select></label>
            {selectedCard ? <button type="button" className="secondary" onClick={() => setSelectedCard("")}><X size={13} /> Clear card</button> : null}
          </div>
          <div className="replay-intelligence-timeline-summary">
            <span>{filteredEvents.length} of {result.events.length} events</span>
            <span>{model.replay.video ? "Select a row to jump to video" : "Timeline reconstructed without local video"}</span>
          </div>
          <div className="replay-intelligence-event-list">
            {filteredEvents.map((event) => (
              <ReplayIntelligenceEventRow
                event={event}
                replay={model.replay}
                key={event.id}
                onSeek={onSeek}
                onEdit={() => setEditingEvent(event)}
              />
            ))}
            {!filteredEvents.length ? <div className="replay-intelligence-empty"><Eye size={22} /><strong>No matching evidence</strong><span>Clear a filter or search for another card or action.</span></div> : null}
          </div>
        </div>
      ) : null}

      {tab === "cards" ? (
        <div className="replay-intelligence-card-journeys">
          <p>These journeys join only events with the same visible card identity, player and game. Hover the artwork to inspect it; open a journey to isolate its evidence.</p>
          <div className="replay-intelligence-card-grid">
            {summary.cardJourneys.map((journey) => {
              const imageUrl = replayIntelligenceCardImage(journey.cardId, journey.cardName);
              return (
                <button type="button" key={journey.id} onClick={() => openCardJourney(replayIntelligenceCardKey(journey.cardId || journey.cardName))}>
                  <ReplayIntelligenceCardArt imageUrl={imageUrl} cardName={journey.cardName} />
                  <span className="replay-intelligence-card-copy">
                    <small>Game {journey.gameNumber} · {journey.side === "me" ? "Player" : journey.side === "opponent" ? "Opponent" : "Observed"}</small>
                    <strong>{journey.cardName}</strong>
                    <em>{journey.events.length} action{journey.events.length === 1 ? "" : "s"} · {replayIntelligenceConfidenceLabel(journey.confidence)}</em>
                    <span>{journey.outcomes.length ? journey.outcomes.join(" → ") : "visible card reference"}</span>
                    {journey.knownHandTimeMs ? <b>Known in hand about {formatDuration(journey.knownHandTimeMs)}</b> : null}
                  </span>
                </button>
              );
            })}
          </div>
          {!summary.cardJourneys.length ? <div className="replay-intelligence-empty"><Eye size={22} /><strong>No named card journeys</strong><span>The source did not expose enough card identities for this replay.</span></div> : null}
        </div>
      ) : null}

      {status ? <p className="replay-intelligence-status" role="status">{status}</p> : null}
      {editingEvent ? (
        <ReplayIntelligenceCorrectionEditor
          event={editingEvent}
          replay={model.replay}
          correction={summary.corrections.find((item) => item.eventId === editingEvent.id)}
          saving={saving}
          onCancel={() => setEditingEvent(null)}
          onSave={(correction) => void saveIntelligence([
            ...summary.corrections.filter((item) => item.eventId !== correction.eventId),
            correction
          ], "Correction saved. The original capture evidence remains unchanged.")}
          onReset={() => void saveIntelligence(summary.corrections.filter((item) => item.eventId !== editingEvent.id), "Manual correction removed.")}
          onDismiss={() => void saveIntelligence([
            ...summary.corrections.filter((item) => item.eventId !== editingEvent.id),
            {
              id: summary.corrections.find((item) => item.eventId === editingEvent.id)?.id ?? createLocalId("replay-correction"),
              eventId: editingEvent.id,
              updatedAt: new Date().toISOString(),
              dismissed: true,
              note: "Dismissed during replay review."
            }
          ], "Event dismissed from Replay Intelligence. The source evidence was retained.")}
        />
      ) : null}
    </section>
  );
}

function ReplayIntelligenceStat({ label, value }: { label: string; value: number }) {
  return <div><span>{label}</span><strong>{value}</strong></div>;
}

function ReplayIntelligenceEventRow({
  event,
  replay,
  onSeek,
  onEdit
}: {
  event: ReplayIntelligenceEvent;
  replay: ReplayRecord;
  onSeek: (timeMs: number) => void;
  onEdit: () => void;
}) {
  const imageUrl = replayIntelligenceCardImage(event.cardId, event.cardName);
  return (
    <article className="replay-intelligence-event" data-type={event.type} data-side={event.side} data-confidence={event.confidence}>
      <button type="button" className="replay-intelligence-event-main" onClick={() => typeof event.videoTimeMs === "number" && onSeek(event.videoTimeMs)} disabled={typeof event.videoTimeMs !== "number"}>
        <span className="replay-intelligence-event-time">
          <strong>{typeof event.videoTimeMs === "number" ? formatDuration(event.videoTimeMs) : event.labelTime}</strong>
          <small>{event.turnLabel || `Game ${event.gameNumber ?? 1}`}</small>
        </span>
        {event.cardName || event.cardId ? <ReplayIntelligenceCardArt imageUrl={imageUrl} cardName={event.cardName || event.cardId || "Card"} compact /> : <span className="replay-intelligence-event-node" />}
        <span className="replay-intelligence-event-copy">
          <span><b>{event.type.replace("-", " ")}</b><i data-confidence={event.confidence}>{replayIntelligenceConfidenceLabel(event.confidence)}</i>{event.corrected ? <i>corrected</i> : null}</span>
          <strong>{event.text || event.cardName || "Captured event"}</strong>
          {replayEventMetadata(event) ? <small>{replayEventMetadata(event)}</small> : null}
          <em>{event.confidenceReason}{event.correctionNote ? ` ${event.correctionNote}` : ""}</em>
        </span>
        {event.score ? <span className="replay-intelligence-score">{event.score.me ?? "-"}<small>score</small>{event.score.opponent ?? "-"}</span> : null}
        {typeof event.videoTimeMs === "number" ? <Play className="replay-intelligence-play" size={15} /> : null}
      </button>
      <button type="button" className="replay-intelligence-correct" onClick={onEdit}>{event.corrected ? "Edit correction" : "Correct"}</button>
    </article>
  );
}

function ReplayIntelligenceCardArt({ imageUrl, cardName, compact = false }: { imageUrl: string; cardName: string; compact?: boolean }) {
  return (
    <span className={`replay-intelligence-card-art${compact ? " compact" : ""}`}>
      {imageUrl ? <img src={imageUrl} alt={cardName} loading="lazy" draggable={false} /> : <strong>{cardName.slice(0, 2).toUpperCase()}</strong>}
      {imageUrl ? <span className="replay-intelligence-card-preview"><img src={imageUrl} alt={`${cardName} enlarged`} /></span> : null}
    </span>
  );
}

function ReplayIntelligenceCorrectionEditor({
  event,
  replay,
  correction,
  saving,
  onSave,
  onReset,
  onDismiss,
  onCancel
}: {
  event: ReplayIntelligenceEvent;
  replay: ReplayRecord;
  correction?: ReplayIntelligenceCorrection;
  saving: boolean;
  onSave: (correction: ReplayIntelligenceCorrection) => void;
  onReset: () => void;
  onDismiss: () => void;
  onCancel: () => void;
}) {
  const initialSeconds = typeof event.videoTimeMs === "number" ? Math.round(event.videoTimeMs / 1000) : 0;
  const [draft, setDraft] = useState(() => ({
    type: correction?.type ?? event.type,
    side: correction?.side ?? event.side,
    text: correction?.text ?? event.text,
    cardName: correction?.cardName ?? event.cardName,
    cardId: correction?.cardId ?? event.cardId ?? "",
    fromZone: correction?.fromZone ?? event.fromZone ?? "",
    toZone: correction?.toZone ?? event.toZone ?? "",
    destination: correction?.destination ?? event.destination,
    battlefield: correction?.battlefield ?? event.battlefield,
    pointsScored: String(correction?.pointsScored ?? event.pointsScored ?? ""),
    videoSeconds: String(initialSeconds),
    note: correction?.note ?? event.correctionNote
  }));
  const knownTypes: ReplayIntelligenceEvent["type"][] = ["setup", "mulligan", "turn-start", "turn-end", "draw", "play", "move", "score", "combat", "battlefield", "scoreboard", "result", "action"];
  function submit() {
    const seconds = Number(draft.videoSeconds);
    const videoBase = Date.parse(replay.video?.startedAt || replay.capturedAt);
    const capturedAt = replay.video && Number.isFinite(seconds) && Number.isFinite(videoBase)
      ? new Date(videoBase + Math.max(0, seconds) * 1000).toISOString()
      : correction?.capturedAt;
    const points = Number(draft.pointsScored);
    onSave({
      id: correction?.id ?? createLocalId("replay-correction"),
      eventId: event.id,
      updatedAt: new Date().toISOString(),
      capturedAt,
      type: draft.type,
      side: draft.side,
      text: draft.text.trim(),
      cardName: draft.cardName.trim(),
      cardId: draft.cardId.trim(),
      fromZone: draft.fromZone.trim(),
      toZone: draft.toZone.trim(),
      destination: draft.destination.trim(),
      battlefield: draft.battlefield.trim(),
      pointsScored: Number.isFinite(points) && draft.pointsScored.trim() ? points : undefined,
      note: draft.note.trim()
    });
  }
  return (
    <div className="replay-intelligence-editor-backdrop" role="presentation" onMouseDown={(mouseEvent) => mouseEvent.target === mouseEvent.currentTarget && onCancel()}>
      <section className="replay-intelligence-editor" role="dialog" aria-modal="true" aria-label="Correct replay event">
        <header><div><span>Manual evidence layer</span><h3>Correct replay event</h3></div><button type="button" className="secondary" onClick={onCancel}><X size={15} /></button></header>
        <p>The captured source is preserved. This correction changes only the reconstructed Replay Intelligence view.</p>
        <div className="replay-intelligence-editor-grid">
          <label>Event type<select value={draft.type} onChange={(changeEvent) => setDraft({ ...draft, type: changeEvent.target.value as ReplayIntelligenceEvent["type"] })}>{knownTypes.map((type) => <option value={type} key={type}>{type.replace("-", " ")}</option>)}</select></label>
          <label>Side<select value={draft.side} onChange={(changeEvent) => setDraft({ ...draft, side: changeEvent.target.value as ReplayIntelligenceEvent["side"] })}><option value="me">Player</option><option value="opponent">Opponent</option><option value="system">System</option><option value="unknown">Unknown</option></select></label>
          {replay.video ? <label>Video time (seconds)<input type="number" min="0" max={Math.ceil(replay.video.durationMs / 1000)} value={draft.videoSeconds} onChange={(changeEvent) => setDraft({ ...draft, videoSeconds: changeEvent.target.value })} /></label> : null}
          <label>Points scored<input type="number" min="-20" max="20" value={draft.pointsScored} onChange={(changeEvent) => setDraft({ ...draft, pointsScored: changeEvent.target.value })} /></label>
          <label className="wide">Description<input value={draft.text} onChange={(changeEvent) => setDraft({ ...draft, text: changeEvent.target.value })} /></label>
          <label>Card name<input value={draft.cardName} onChange={(changeEvent) => setDraft({ ...draft, cardName: changeEvent.target.value })} /></label>
          <label>Card code<input value={draft.cardId} onChange={(changeEvent) => setDraft({ ...draft, cardId: changeEvent.target.value })} /></label>
          <label>From zone<input value={draft.fromZone} onChange={(changeEvent) => setDraft({ ...draft, fromZone: changeEvent.target.value })} /></label>
          <label>To zone<input value={draft.toZone} onChange={(changeEvent) => setDraft({ ...draft, toZone: changeEvent.target.value })} /></label>
          <label>Destination<input value={draft.destination} onChange={(changeEvent) => setDraft({ ...draft, destination: changeEvent.target.value })} /></label>
          <label>Battlefield<input value={draft.battlefield} onChange={(changeEvent) => setDraft({ ...draft, battlefield: changeEvent.target.value })} /></label>
          <label className="wide">Reviewer note<textarea value={draft.note} onChange={(changeEvent) => setDraft({ ...draft, note: changeEvent.target.value })} placeholder="Why was this changed?" /></label>
        </div>
        <footer>
          <div><button type="button" className="secondary danger" disabled={saving} onClick={onDismiss}>Dismiss event</button>{correction ? <button type="button" className="secondary" disabled={saving} onClick={onReset}>Reset correction</button> : null}</div>
          <div><button type="button" className="secondary" onClick={onCancel}>Cancel</button><button type="button" className="primary" disabled={saving || !draft.text.trim()} onClick={submit}><Save size={14} /> Save correction</button></div>
        </footer>
      </section>
    </div>
  );
}

function replayIntelligenceConfidenceLabel(value: ReplayIntelligenceConfidence): string {
  if (value === "confirmed") return "Confirmed";
  if (value === "reconstructed") return "Reconstructed";
  if (value === "manual") return "Manual";
  return "Inferred";
}

function replayIntelligenceCardKey(value: string): string {
  return value.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function replayIntelligenceCardImage(cardId = "", cardName = ""): string {
  const registryCard = REPLAY_INTELLIGENCE_CARD_BY_NAME.get(cardName.trim().toLowerCase());
  return resolveBundledReplayCardImage(cardId || registryCard?.code || "")
    || registryCard?.imageUrl
    || deckTrackerImageUrlFromId(cardId || registryCard?.code || "");
}

function ReplayHealthPanel({
  model,
  screenshots,
  layers,
  flags,
  annotations,
  voiceNotes
}: {
  model: AtlasReplayViewModel;
  screenshots: AtlasReplayViewModel["screenshots"];
  layers: ReplayTeachingLayer[];
  flags: ReplayFlag[];
  annotations: ReplayAnnotation[];
  voiceNotes: ReplayVoiceNote[];
}) {
  const video = model.replay.video;
  const webReplayReady = hasReadyRiftLiteWebReplay(model.replay);
  const warnings: string[] = [];
  if (!video && !screenshots.length) {
    warnings.push(webReplayReady
      ? "Web replay is ready; local video or frame capture was unavailable"
      : "No visual replay media attached");
  }
  if (video && !video.containerFinalized && video.mimeType === "video/mp4") {
    warnings.push("MP4 may still need repair for external players");
  }
  if (video && (!video.width || !video.height || !video.durationMs)) {
    warnings.push("Video metadata is incomplete");
  }
  if (video && video.source !== "game-frame-direct" && video.source !== "riftreplay") {
    warnings.push("Recorded with fallback capture");
  }
  const tone = warnings.length ? "warn" : "good";
  const teachingCount = flags.length + annotations.length + voiceNotes.length;
  return (
    <section className="rail-card replay-health-panel" data-tone={tone}>
      <div className="replay-health-title">
        <div>
          <h2>Replay health</h2>
          <span>{warnings.length ? warnings[0] : "Replay media and teaching data look ready."}</span>
        </div>
        <strong>{warnings.length ? "Check" : "Healthy"}</strong>
      </div>
      <div className="replay-health-grid">
        <StatRow label="Video" value={video ? `${video.width}x${video.height} ${video.fps}fps` : "Off"} />
        <StatRow label="Container" value={video ? (video.containerFinalized ? "Seekable" : "Needs check") : "No video"} />
        <StatRow label="Frames" value={String(screenshots.length)} />
        <StatRow label="Teaching" value={`${teachingCount} item${teachingCount === 1 ? "" : "s"}`} />
        <StatRow label="Layers" value={String(layers.length)} />
        <StatRow label="Source" value={video ? (video.source === "riftreplay" ? "Imported" : video.source.replace(/-/g, " ")) : model.platformLabel} />
      </div>
      {warnings.length > 1 ? (
        <ul>
          {warnings.slice(1).map((warning) => <li key={warning}>{warning}</li>)}
        </ul>
      ) : null}
    </section>
  );
}

function ReplayRawCapturePanel({
  replay,
  settings,
  status,
  onUpload,
  onShareDiscord,
  onRevealSource
}: {
  replay: ReplayRecord;
  settings: UserSettings;
  status: string;
  onUpload: () => void;
  onShareDiscord: () => void;
  onRevealSource: () => void;
}) {
  const rawCapture = replay.rawCapture;
  if (!settings.rawCapture.enabled && !rawCapture) {
    return null;
  }
  const deliverySummary = replayDeliverySummary(rawCapture, settings.rawCapture.enabled);
  const hasRiftLiteReplay = Boolean(rawCapture?.uploadUrl?.includes("riftlite.com/replays/"));
  const accountReady = hasVerifiedRiftLiteAccount(settings);
  const canUpload = Boolean(
    settings.rawCapture.enabled &&
    accountReady &&
    rawCapture?.localPath &&
    !hasRiftLiteReplay
  );
  const activeHubIds = new Set(settings.activeHubs.map((hub) => hub.id));
  const discordHubIds = activeDiscordReplayHubIds(settings).filter((hubId) => activeHubIds.has(hubId));
  const canShareDiscord = Boolean(
    accountReady &&
    (replay.platform === "atlas" || replay.platform === "tcga") &&
    hasRiftLiteReplay &&
    discordHubIds.length
  );
  const discordShared = rawCapture?.discordShareStatus === "shared";
  const deliveryStages = replayDeliveryStages(rawCapture);
  return (
    <section className="rail-card replay-health-panel">
      <div className="replay-health-title">
        <div>
          <h2>RiftLite web replay capture</h2>
          <span>{rawCapture
            ? `${rawCapture.messageCount} ${replay.platform === "tcga" ? "TCGA game message" : "Atlas WebSocket frame"}${rawCapture.messageCount === 1 ? "" : "s"} captured.`
            : `No ${replay.platform === "tcga" ? "TCGA game-channel capture" : "raw Atlas sidecar"} is attached to this replay.`}</span>
        </div>
        <strong>{deliverySummary.statusLabel}</strong>
      </div>
      <div className="replay-health-grid">
        <StatRow label="Provider" value="RiftLite Web Replay" />
        <StatRow label="Source" value={replay.platform === "tcga" ? "TCGA game channel" : "Atlas WebSocket"} />
        <StatRow label="Room" value={replay.platform === "tcga" ? "Not applicable" : rawCapture?.roomCode || "Not captured"} />
        <StatRow label="Visibility" value={rawCapture?.visibility || settings.rawCapture.visibility} />
        <StatRow label="Uploaded" value={rawCapture?.uploadedAt ? new Date(rawCapture.uploadedAt).toLocaleString() : deliverySummary.uploadLabel} />
        <StatRow label="Discord reports" value={deliverySummary.discordLabel} />
      </div>

      <div className="replay-delivery-stages" aria-label="Replay delivery progress">
        {deliveryStages.map((stage) => (
          <div className="replay-delivery-stage" data-state={stage.state} key={stage.id}>
            <span className="replay-delivery-marker" aria-hidden="true">
              {stage.state === "complete" ? <Check size={14} /> : stage.state === "failed" ? <AlertTriangle size={14} /> : <Activity size={14} />}
            </span>
            <div>
              <strong>{stage.label}</strong>
              <small>{stage.detail}{stage.timestamp ? ` · ${new Date(stage.timestamp).toLocaleString()}` : ""}</small>
            </div>
          </div>
        ))}
      </div>
      {hasRiftLiteReplay && rawCapture?.uploadUrl ? (
        <div className="row-actions">
          <button className="secondary" type="button" onClick={() => void window.riftlite.openExternalResource(rawCapture.uploadUrl!)}>
            <ExternalLink size={14} /> Open web replay
          </button>
          <button
            className="secondary"
            type="button"
            disabled={!canShareDiscord || discordShared}
            onClick={onShareDiscord}
            title={canShareDiscord
              ? "Makes this replay Unlisted and posts its permanent link to the selected hub Discord reports channel."
              : "Select a Discord replay destination from the Account tab first."}
          >
            <Radio size={14} /> {discordShared ? "Shared to Discord" : rawCapture?.discordShareStatus === "failed" ? "Retry Discord share" : "Share to Discord"}
          </button>
        </div>
      ) : (
        <button
          className="secondary"
          type="button"
          disabled={!canUpload}
          onClick={onUpload}
          title={!accountReady ? "Open Account and finish verification before uploading." : undefined}
        >
          <Upload size={14} /> Upload to web replay
        </button>
      )}
      {rawCapture?.localPath ? (
        <button className="secondary" type="button" onClick={onRevealSource}>
          <FolderOpen size={14} /> Show source file
        </button>
      ) : null}
      {!accountReady && rawCapture?.localPath ? (
        <p className="muted">The replay is saved locally. Open Account and finish verification or reconnect the same account before retrying.</p>
      ) : null}
      {rawCapture?.error ? <p className="muted">{replayDeliveryErrorMessage(rawCapture.error, {
        code: rawCapture.lastErrorCode,
        errorClass: rawCapture.lastErrorClass,
        httpStatus: rawCapture.lastHttpStatus,
        nextRetryAt: rawCapture.nextRetryAt
      })}</p> : null}
      {rawCapture?.discordShareError ? <p className="muted">{rawCapture.discordShareError}</p> : null}
      {status ? <p className="muted">{status}</p> : null}
    </section>
  );
}

function replayScreenshots(model: AtlasReplayViewModel): AtlasReplayViewModel["screenshots"] {
  const seen = new Set<string>();
  return [...model.screenshots]
    .filter((screenshot) => {
      const key = screenshotKey(screenshot);
      if (!key || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .sort((a, b) => new Date(a.capturedAt).getTime() - new Date(b.capturedAt).getTime());
}

function trimmedReplayScreenshots(
  screenshots: AtlasReplayViewModel["screenshots"],
  trim?: ReplayTrimRange
): AtlasReplayViewModel["screenshots"] {
  if (!trim) {
    return screenshots;
  }
  const trimmed = screenshots.filter((screenshot) => withinTrimRange(screenshot.capturedAt, trim));
  return trimmed.length ? trimmed : screenshots;
}

function replayTrimSavings(allScreenshots: AtlasReplayViewModel["screenshots"], trimmedScreenshots: AtlasReplayViewModel["screenshots"]): string {
  if (!allScreenshots.length) {
    return "0";
  }
  if (trimmedScreenshots.length >= allScreenshots.length) {
    return `${allScreenshots.length}`;
  }
  return `${trimmedScreenshots.length}/${allScreenshots.length}`;
}

function screenshotKey(screenshot: AtlasReplayViewModel["screenshots"][number]): string {
  return `${screenshot.path || screenshot.url}|${screenshot.capturedAt}|${screenshot.label}`;
}

function replayFrameTargetId(screenshot: AtlasReplayViewModel["screenshots"][number]): string {
  return screenshotKey(screenshot);
}

function withinTrimRange(capturedAt: string, trim: ReplayTrimRange): boolean {
  const time = new Date(capturedAt).getTime();
  const start = new Date(trim.startCapturedAt).getTime();
  const end = new Date(trim.endCapturedAt).getTime();
  if (!Number.isFinite(time) || !Number.isFinite(start) || !Number.isFinite(end)) {
    return true;
  }
  return time >= Math.min(start, end) && time <= Math.max(start, end);
}

function replayVideoCapturedAt(video: ReplayVideoAsset, timeMs: number): string {
  const base = new Date(video.startedAt).getTime();
  return new Date((Number.isFinite(base) ? base : Date.now()) + Math.max(0, timeMs)).toISOString();
}

function formatDuration(valueMs: number): string {
  const seconds = Math.max(0, Math.round(valueMs / 1000));
  const minutes = Math.floor(seconds / 60);
  const remaining = seconds % 60;
  return `${minutes}:${remaining.toString().padStart(2, "0")}`;
}

function matchTimerLabelFromReplay(replay: ReplayRecord | undefined): string {
  const durationMs = replay?.video?.durationMs;
  if (typeof durationMs !== "number" || !Number.isFinite(durationMs) || durationMs <= 0) {
    return "";
  }
  return formatDuration(durationMs);
}

function replayFlagTypeLabel(flag: Pick<ReplayFlag, "type" | "customType" | "label">): string {
  if (flag.type === "custom") {
    return flag.customType?.trim() || flag.label || "Custom";
  }
  return REPLAY_FLAG_TYPES.find((item) => item.value === flag.type)?.label || flag.label || "Key turn";
}

function normaliseCustomReplayFlagType(value: string): string {
  return value.trim().replace(/\s+/g, " ").slice(0, 48);
}

function replayFlagSelectValue(flagType: ReplayFlagType, customType: string, customFlagTypes: string[]): string {
  if (flagType !== "custom") {
    return flagType;
  }
  const normalized = normaliseCustomReplayFlagType(customType);
  const saved = customFlagTypes.find((item) => item.toLowerCase() === normalized.toLowerCase());
  return saved ? `${CUSTOM_REPLAY_FLAG_PREFIX}${saved}` : "custom";
}

function replayFlagTypeOptions(customFlagTypes: string[]): Array<{ value: string; label: string }> {
  const customOptions = customFlagTypes
    .map(normaliseCustomReplayFlagType)
    .filter(Boolean)
    .filter((label, index, all) => all.findIndex((item) => item.toLowerCase() === label.toLowerCase()) === index)
    .map((label) => ({ value: `${CUSTOM_REPLAY_FLAG_PREFIX}${label}`, label }));
  return [
    ...REPLAY_FLAG_TYPES.filter((item) => item.value !== "custom"),
    ...customOptions,
    { value: "custom", label: "Custom..." }
  ];
}

function rendererErrorMessage(error: unknown, fallback: string): string {
  if (error instanceof Error) {
    return error.message || fallback;
  }
  const text = String(error ?? "").trim();
  return text || fallback;
}

function replayFlagSortMs(flag: ReplayFlag): number {
  if (typeof flag.timeMs === "number") {
    return flag.timeMs;
  }
  const captured = new Date(flag.capturedAt).getTime();
  return Number.isFinite(captured) ? captured : 0;
}

function replayFlagTypeFromLabel(label: string): ReplayFlagType {
  const normalized = label.trim().toLowerCase();
  if (normalized.includes("mistake")) return "mistake";
  if (normalized.includes("good")) return "good-line";
  if (normalized.includes("lethal")) return "missed-lethal";
  if (normalized.includes("battlefield")) return "battlefield-decision";
  if (normalized.includes("rules")) return "rules-check";
  if (normalized.includes("custom")) return "custom";
  return "key-turn";
}

function replayLayerId(value: string | undefined): string {
  return value?.trim() || DEFAULT_REPLAY_LAYER_ID;
}

function replayLayersFor(replay: ReplayRecord, username = ""): ReplayTeachingLayer[] {
  const base: ReplayTeachingLayer = {
    id: DEFAULT_REPLAY_LAYER_ID,
    name: "Original review",
    author: replay.players?.me || username || "Player",
    color: "#7df9ff",
    createdAt: replay.capturedAt || new Date().toISOString()
  };
  const layers = replay.layers?.length ? replay.layers : [base];
  return layers.some((layer) => layer.id === DEFAULT_REPLAY_LAYER_ID) ? layers : [base, ...layers];
}

function replayCoachingPackDraft(replay: ReplayRecord, username = ""): NonNullable<ReplayRecord["coachingPack"]> {
  return {
    title: replay.coachingPack?.title || replay.title || "RiftLite coaching pack",
    author: replay.coachingPack?.author || username || replay.players?.me || "RiftLite player",
    purpose: replay.coachingPack?.purpose || "Review",
    summary: replay.coachingPack?.summary || replay.matchSnapshot?.notes || "",
    createdAt: replay.coachingPack?.createdAt || new Date().toISOString(),
    updatedAt: replay.coachingPack?.updatedAt
  };
}

function uniqueReplayLayerName(layers: ReplayTeachingLayer[], baseName: string): string {
  const trimmedBase = baseName.trim() || "Coach review";
  const existing = new Set(layers.map((layer) => layer.name.trim().toLowerCase()));
  if (!existing.has(trimmedBase.toLowerCase())) {
    return trimmedBase;
  }
  for (let index = 2; index < 100; index += 1) {
    const candidate = `${trimmedBase} ${index}`;
    if (!existing.has(candidate.toLowerCase())) {
      return candidate;
    }
  }
  return `${trimmedBase} ${Date.now()}`;
}

function blobToDataUrl(blob: Blob): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(typeof reader.result === "string" ? reader.result : "");
    reader.onerror = () => reject(reader.error ?? new Error("Could not read voice note."));
    reader.readAsDataURL(blob);
  });
}

type VoiceRecorderCapture = {
  recorder: MediaRecorder;
  cleanup: () => void;
};

type VoiceStreamCapture = {
  stream: MediaStream;
  cleanup: () => void;
};

async function createVoiceStreamCapture(microphoneDeviceId: string): Promise<VoiceStreamCapture> {
  const rawAudio: MediaTrackConstraints = {
    ...(microphoneDeviceId ? { deviceId: { exact: microphoneDeviceId } } : {}),
    echoCancellation: false,
    noiseSuppression: false,
    autoGainControl: false,
    channelCount: 1,
    sampleRate: 48_000,
    sampleSize: 16
  };
  let sourceStream: MediaStream;
  try {
    sourceStream = await navigator.mediaDevices.getUserMedia({ audio: rawAudio });
  } catch {
    sourceStream = await navigator.mediaDevices.getUserMedia({
      audio: microphoneDeviceId ? { deviceId: { exact: microphoneDeviceId } } : true
    });
  }
  const sourceTrack = sourceStream.getAudioTracks()[0];
  await sourceTrack?.applyConstraints({
    echoCancellation: false,
    noiseSuppression: false,
    autoGainControl: false,
    channelCount: 1,
    sampleRate: 48_000,
    sampleSize: 16
  }).catch(() => undefined);

  let recorderStream = sourceStream;
  let audioContext: AudioContext | null = null;
  try {
    audioContext = new AudioContext({ sampleRate: 48_000, latencyHint: "interactive" });
    const source = audioContext.createMediaStreamSource(sourceStream);
    const gain = audioContext.createGain();
    const destination = audioContext.createMediaStreamDestination();
    gain.gain.value = 1;
    source.connect(gain);
    gain.connect(destination);
    recorderStream = destination.stream;
  } catch {
    audioContext = null;
    recorderStream = sourceStream;
  }

  let cleaned = false;
  const cleanup = () => {
    if (cleaned) {
      return;
    }
    cleaned = true;
    sourceStream.getTracks().forEach((track) => track.stop());
    recorderStream.getTracks().forEach((track) => track.stop());
    void audioContext?.close().catch(() => undefined);
  };
  return { stream: recorderStream, cleanup };
}

async function createVoiceRecorderCapture(microphoneDeviceId: string): Promise<VoiceRecorderCapture> {
  const capture = await createVoiceStreamCapture(microphoneDeviceId);
  const candidates = ["audio/webm;codecs=opus", "audio/webm", "audio/mp4"];
  const mimeType = candidates.find((candidate) => MediaRecorder.isTypeSupported(candidate)) ?? "";
  const recorder = new MediaRecorder(capture.stream, {
    ...(mimeType ? { mimeType } : {}),
    audioBitsPerSecond: 128_000,
    bitsPerSecond: 128_000
  });
  return { recorder, cleanup: capture.cleanup };
}

function replayVoiceNoteForFlag(notes: ReplayVoiceNote[], flagId: string, layerId?: string): ReplayVoiceNote | undefined {
  return notes.find((note) => note.flagId === flagId && (!layerId || replayLayerId(note.layerId) === layerId))
    ?? notes.find((note) => note.flagId === flagId);
}

function ReplayFlagEditor({
  flag,
  voiceNotes,
  activeLayerId,
  activeLayerName,
  microphoneDeviceId,
  onSave,
  onDelete,
  onSaveVoiceNote,
  onDeleteVoiceNote,
  onCancel
}: {
  flag: ReplayFlag;
  voiceNotes: ReplayVoiceNote[];
  activeLayerId: string;
  activeLayerName: string;
  microphoneDeviceId: string;
  onSave: (flag: ReplayFlag) => void;
  onDelete: () => void;
  onSaveVoiceNote: (voiceNote: ReplayVoiceNote) => void;
  onDeleteVoiceNote: () => void;
  onCancel: () => void;
}) {
  const initialType = flag.type ?? replayFlagTypeFromLabel(flag.label);
  const activeVoiceNote = voiceNotes.find((note) => replayLayerId(note.layerId) === activeLayerId);
  const [type, setType] = useState<ReplayFlagType>(initialType);
  const [customType, setCustomType] = useState(flag.customType ?? (initialType === "custom" ? flag.label : ""));
  const [note, setNote] = useState(flag.note ?? "");
  const [recording, setRecording] = useState(false);
  const [voiceStatus, setVoiceStatus] = useState("");
  const recorderRef = useRef<MediaRecorder | null>(null);
  const recorderCleanupRef = useRef<(() => void) | null>(null);
  const chunksRef = useRef<Blob[]>([]);
  const startedAtRef = useRef(0);
  useEffect(() => () => {
    recorderRef.current?.state === "recording" && recorderRef.current.stop();
    recorderCleanupRef.current?.();
  }, []);
  const save = () => {
    const typeLabel = type === "custom"
      ? customType.trim() || "Custom"
      : REPLAY_FLAG_TYPES.find((item) => item.value === type)?.label || flag.label;
    onSave({
      ...flag,
      type,
      customType: type === "custom" ? customType.trim() : "",
      label: typeLabel,
      note: note.trim(),
      updatedAt: new Date().toISOString()
    });
  };
  async function startVoiceNote() {
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
      setVoiceStatus("Voice recording is not available on this system.");
      return;
    }
    try {
      const capture = await createVoiceRecorderCapture(microphoneDeviceId);
      const recorder = capture.recorder;
      chunksRef.current = [];
      recorderCleanupRef.current = capture.cleanup;
      recorderRef.current = recorder;
      startedAtRef.current = Date.now();
      recorder.ondataavailable = (event) => {
        if (event.data.size) {
          chunksRef.current.push(event.data);
        }
      };
      recorder.onstop = () => {
        const durationMs = Date.now() - startedAtRef.current;
        const blob = new Blob(chunksRef.current, { type: recorder.mimeType || "audio/webm" });
        recorderCleanupRef.current?.();
        recorderCleanupRef.current = null;
        recorderRef.current = null;
        setRecording(false);
        if (!blob.size) {
          setVoiceStatus("No voice note was captured.");
          return;
        }
        void blobToDataUrl(blob)
          .then((dataUrl) => {
            onSaveVoiceNote({
              id: activeVoiceNote?.id ?? crypto.randomUUID(),
              flagId: flag.id,
              layerId: activeLayerId,
              mimeType: blob.type || "audio/webm",
              dataUrl,
              durationMs,
              sizeBytes: blob.size,
              createdAt: activeVoiceNote?.createdAt ?? new Date().toISOString(),
              updatedAt: new Date().toISOString()
            });
            setVoiceStatus(`Saved voice note (${formatDuration(durationMs)}).`);
          })
          .catch(() => setVoiceStatus("Could not save voice note."));
      };
      recorder.start();
      setRecording(true);
      setVoiceStatus("Recording voice note...");
    } catch (error) {
      setRecording(false);
      recorderCleanupRef.current?.();
      recorderCleanupRef.current = null;
      setVoiceStatus(error instanceof Error ? error.message : "Microphone access was blocked.");
    }
  }
  function stopVoiceNote() {
    if (recorderRef.current?.state === "recording") {
      recorderRef.current.stop();
    }
  }
  return (
    <div className="modal-backdrop replay-editor-backdrop" onClick={onCancel}>
      <section className="rail-card replay-flag-editor" onClick={(event) => event.stopPropagation()}>
        <header>
          <div>
            <h2>Edit replay flag</h2>
            <span>{flag.targetLabel}</span>
          </div>
          <button type="button" className="icon-button" onClick={onCancel} title="Close flag editor">
            <X size={16} />
          </button>
        </header>
        <label>
          Type
          <select value={type} onChange={(event) => setType(event.target.value as ReplayFlagType)}>
            {REPLAY_FLAG_TYPES.map((item) => (
              <option value={item.value} key={item.value}>{item.label}</option>
            ))}
          </select>
        </label>
        {type === "custom" ? (
          <label>
            Custom label
            <input value={customType} onChange={(event) => setCustomType(event.target.value)} placeholder="Coach label..." />
          </label>
        ) : null}
        <label>
          Note
          <textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="What should the viewer learn here?" />
        </label>
        <div className="replay-voice-note-panel">
          <div>
            <strong><Mic size={14} /> Voice note</strong>
            <span>Recording onto {activeLayerName}. Only records when you press record. Exported .riftreplay files include saved voice notes.</span>
          </div>
          {activeVoiceNote ? (
            <audio controls src={activeVoiceNote.dataUrl} />
          ) : (
            <p className="muted">No voice note attached to this flag on the active layer.</p>
          )}
          {voiceNotes.filter((note) => replayLayerId(note.layerId) !== activeLayerId).map((note) => (
            <div className="replay-voice-note-extra" key={note.id}>
              <span>Other layer note - {formatDuration(note.durationMs)}</span>
              <audio controls src={note.dataUrl} />
            </div>
          ))}
          <div className="row-actions">
            <button type="button" className={recording ? "danger" : "secondary"} onClick={() => recording ? stopVoiceNote() : void startVoiceNote()}>
              <Mic size={14} /> {recording ? "Stop recording" : activeVoiceNote ? "Re-record" : "Record"}
            </button>
            <button type="button" className="secondary danger" disabled={!activeVoiceNote || recording} onClick={onDeleteVoiceNote}>
              Delete voice
            </button>
          </div>
          {voiceStatus ? <span className="replay-status-text">{voiceStatus}</span> : null}
        </div>
        <div className="row-actions">
          <button type="button" className="primary" onClick={save}><Save size={14} /> Save flag</button>
          <button type="button" className="secondary danger" onClick={onDelete}>Delete flag</button>
          <button type="button" className="secondary" onClick={onCancel}>Cancel</button>
        </div>
      </section>
    </div>
  );
}

function ReplayAnnotationCanvas({
  annotations,
  targetId,
  targetLabel,
  capturedAt,
  timeMs,
  layerId,
  activeClipId,
  activeClipStartedAt,
  playbackClipId,
  playbackOffsetMs,
  onAddAnnotation,
  onRemoveAnnotation,
  onRemoveAnnotations
}: {
  annotations: ReplayAnnotation[];
  targetId: string;
  targetLabel: string;
  capturedAt: string;
  timeMs?: number;
  layerId: string;
  activeClipId?: string;
  activeClipStartedAt?: number;
  playbackClipId?: string;
  playbackOffsetMs?: number;
  onAddAnnotation: (annotation: ReplayAnnotation) => void;
  onRemoveAnnotation: (id: string) => void;
  onRemoveAnnotations: (ids: string[]) => void;
}) {
  const [tool, setTool] = useState<ReplayAnnotationTool>("pen");
  const [color, setColor] = useState(REPLAY_ANNOTATION_COLORS[0]);
  const [draftPoints, setDraftPoints] = useState<Array<{ x: number; y: number }>>([]);
  const [drawing, setDrawing] = useState(false);
  const [toolsOpen, setToolsOpen] = useState(false);
  const [pendingTextAnnotation, setPendingTextAnnotation] = useState<PendingReplayTextAnnotation | null>(null);
  const [textDraft, setTextDraft] = useState("");
  const normalisePoint = (event: React.PointerEvent<SVGSVGElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    return {
      x: Math.min(1, Math.max(0, (event.clientX - rect.left) / Math.max(1, rect.width))),
      y: Math.min(1, Math.max(0, (event.clientY - rect.top) / Math.max(1, rect.height)))
    };
  };
  const clipFields = (): Pick<ReplayAnnotation, "clipId" | "offsetMs"> => activeClipId
    ? {
        clipId: activeClipId,
        offsetMs: Math.max(0, Date.now() - (activeClipStartedAt ?? Date.now()))
      }
    : {};
  const start = (event: React.PointerEvent<SVGSVGElement>) => {
    event.preventDefault();
    const point = normalisePoint(event);
    if (tool === "text") {
      setTextDraft("");
      setPendingTextAnnotation({
        targetType: timeMs == null ? "frame" : "video-time",
        targetId,
        targetLabel,
        capturedAt,
        timeMs,
        tool: "text",
        layerId,
        ...clipFields(),
        color,
        width: 2,
        points: [point]
      });
      return;
    }
    event.currentTarget.setPointerCapture(event.pointerId);
    setDrawing(true);
    setDraftPoints([point]);
  };
  const move = (event: React.PointerEvent<SVGSVGElement>) => {
    if (!drawing) {
      return;
    }
    const point = normalisePoint(event);
    setDraftPoints((points) => [...points, point]);
  };
  const finish = () => {
    if (!drawing) {
      return;
    }
    setDrawing(false);
    if (draftPoints.length < 2) {
      setDraftPoints([]);
      return;
    }
    onAddAnnotation({
      id: crypto.randomUUID(),
      targetType: timeMs == null ? "frame" : "video-time",
      targetId,
      targetLabel,
      capturedAt,
      timeMs,
      tool,
      layerId,
      ...clipFields(),
      color,
      width: tool === "highlight" ? 10 : 3,
      points: draftPoints,
      createdAt: new Date().toISOString()
    });
    setDraftPoints([]);
  };
  const cancelTextAnnotation = () => {
    setPendingTextAnnotation(null);
    setTextDraft("");
  };
  const confirmTextAnnotation = () => {
    if (!pendingTextAnnotation) {
      return;
    }
    const annotation = createReplayTextAnnotation(
      pendingTextAnnotation,
      textDraft,
      crypto.randomUUID(),
      new Date().toISOString()
    );
    if (!annotation) {
      return;
    }
    onAddAnnotation(annotation);
    setPendingTextAnnotation(null);
    setTextDraft("");
  };
  const syncedAnnotations = annotations.filter((annotation) => {
    if (!annotation.clipId) {
      return true;
    }
    if (annotation.clipId === activeClipId) {
      return true;
    }
    if (annotation.clipId !== playbackClipId) {
      return false;
    }
    return (annotation.offsetMs ?? 0) <= (playbackOffsetMs ?? 0);
  });
  const visibleAnnotations = draftPoints.length
    ? [...syncedAnnotations, {
        id: "draft",
        targetType: timeMs == null ? "frame" : "video-time",
        targetId,
        targetLabel,
        capturedAt,
        timeMs,
        tool,
        layerId,
        ...clipFields(),
        color,
        width: tool === "highlight" ? 10 : 3,
        points: draftPoints,
        createdAt: new Date().toISOString()
      } satisfies ReplayAnnotation]
    : syncedAnnotations;
  return (
    <div className="replay-whiteboard" data-tools-open={toolsOpen}>
      <button
        type="button"
        className="replay-whiteboard-toggle"
        data-open={toolsOpen}
        onClick={() => setToolsOpen((value) => !value)}
        title={toolsOpen ? "Hide drawing tools" : "Show drawing tools"}
      >
        <SlidersHorizontal size={16} />
        <span>Draw</span>
      </button>
      {toolsOpen ? (
        <div className="replay-whiteboard-toolbar">
          <button type="button" className="icon-button" onClick={() => setToolsOpen(false)} title="Hide drawing tools">
            <X size={14} />
          </button>
          {activeClipId ? <strong className="replay-whiteboard-sync">Syncing to voice</strong> : null}
          {playbackClipId ? <strong className="replay-whiteboard-sync">Voice playback</strong> : null}
          <label>
            Tool
            <select value={tool} onChange={(event) => setTool(event.target.value as ReplayAnnotationTool)} title="Whiteboard tool">
              {REPLAY_ANNOTATION_TOOLS.map((item) => (
                <option value={item.value} key={item.value}>{item.label}</option>
              ))}
            </select>
          </label>
          <span>Colour</span>
          <div className="replay-color-picks">
            {REPLAY_ANNOTATION_COLORS.map((item) => (
              <button
                type="button"
                key={item}
                data-active={item === color}
                style={{ background: item }}
                onClick={() => setColor(item)}
                title={`Use ${item}`}
              />
            ))}
          </div>
          <button
            type="button"
            className="secondary"
            disabled={!syncedAnnotations.length}
            onClick={() => {
              const last = syncedAnnotations.at(-1);
              if (last) {
                onRemoveAnnotation(last.id);
              }
            }}
          >
            Undo mark
          </button>
          <button
            type="button"
            className="secondary"
            disabled={!syncedAnnotations.length}
            onClick={() => onRemoveAnnotations(syncedAnnotations.map((annotation) => annotation.id))}
          >
            Clear marks
          </button>
        </div>
      ) : null}
      <svg
        className="replay-annotation-svg"
        data-drawing-enabled={toolsOpen}
        viewBox="0 0 1000 1000"
        preserveAspectRatio="none"
        onPointerDown={start}
        onPointerMove={move}
        onPointerUp={finish}
        onPointerCancel={finish}
      >
        <defs>
          <marker id="replay-arrow-head" markerWidth="10" markerHeight="10" refX="8" refY="3" orient="auto" markerUnits="strokeWidth">
            <path d="M0,0 L0,6 L9,3 z" fill="currentColor" />
          </marker>
        </defs>
        {visibleAnnotations.map((annotation) => (
          <ReplayAnnotationShape annotation={annotation} key={annotation.id} />
        ))}
      </svg>
      {pendingTextAnnotation ? (
        <ReplayAnnotationTextDialog
          targetLabel={pendingTextAnnotation.targetLabel}
          value={textDraft}
          onChange={setTextDraft}
          onCancel={cancelTextAnnotation}
          onConfirm={confirmTextAnnotation}
        />
      ) : null}
    </div>
  );
}

function ReplayAnnotationShape({ annotation }: { annotation: ReplayAnnotation }) {
  const points = annotation.points.map((point) => `${Math.round(point.x * 1000)},${Math.round(point.y * 1000)}`).join(" ");
  const first = annotation.points[0];
  const last = annotation.points.at(-1);
  if (annotation.tool === "text" && first) {
    return (
      <text x={first.x * 1000} y={first.y * 1000} fill={annotation.color} fontSize="42" fontWeight="900" dominantBaseline="middle" paintOrder="stroke" stroke="#020712" strokeWidth="10">
        {annotation.text}
      </text>
    );
  }
  if (annotation.tool === "arrow" && first && last) {
    return (
      <line
        x1={first.x * 1000}
        y1={first.y * 1000}
        x2={last.x * 1000}
        y2={last.y * 1000}
        stroke={annotation.color}
        strokeWidth={annotation.width * 3}
        strokeLinecap="round"
        markerEnd="url(#replay-arrow-head)"
      />
    );
  }
  return (
    <polyline
      points={points}
      fill="none"
      stroke={annotation.color}
      strokeWidth={annotation.width * 3}
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity={annotation.tool === "highlight" ? 0.48 : 0.92}
    />
  );
}

function ReplayVideoPlayer({
  replayId,
  video,
  flags,
  annotations,
  voiceNotes,
  intelligenceEvents,
  seekToMs,
  onSeekHandled,
  onTimeChange,
  flagType,
  flagCustomType,
  flagNote,
  customFlagTypes,
  onFlagTypeSelect,
  onFlagCustomTypeChange,
  onFlagNoteChange,
  onRememberCustomType,
  onFlagTime,
  onEditFlag,
  onSaveKeyframe,
  activeLayerId,
  microphoneDeviceId,
  onSaveTimelineVoiceNote,
  onAddAnnotation,
  onRemoveAnnotation,
  onRemoveAnnotations,
  onClip,
  onExportPresentationMp4
}: {
  replayId: string;
  video: ReplayVideoAsset;
  flags: ReplayFlag[];
  annotations: ReplayAnnotation[];
  voiceNotes: ReplayVoiceNote[];
  intelligenceEvents: ReplayIntelligenceEvent[];
  seekToMs: number | null;
  onSeekHandled: () => void;
  onTimeChange: (timeMs: number) => void;
  flagType: ReplayFlagType;
  flagCustomType: string;
  flagNote: string;
  customFlagTypes: string[];
  onFlagTypeSelect: (value: string) => void;
  onFlagCustomTypeChange: (value: string) => void;
  onFlagNoteChange: (value: string) => void;
  onRememberCustomType: () => void;
  onFlagTime: (timeMs: number) => void;
  onEditFlag: (flag: ReplayFlag) => void;
  onSaveKeyframe: (dataUrl: string, timeMs: number) => Promise<void>;
  activeLayerId: string;
  microphoneDeviceId: string;
  onSaveTimelineVoiceNote: (flag: ReplayFlag, voiceNote: ReplayVoiceNote) => void;
  onAddAnnotation: (annotation: ReplayAnnotation) => void;
  onRemoveAnnotation: (id: string) => void;
  onRemoveAnnotations: (ids: string[]) => void;
  onClip: (timeMs: number) => void;
  onExportPresentationMp4: (replayId: string, payload: ReplayPresentationRecordingPayload) => Promise<string>;
}) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const videoStageRef = useRef<HTMLDivElement | null>(null);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const voiceRecorderRef = useRef<MediaRecorder | null>(null);
  const voiceRecorderCleanupRef = useRef<(() => void) | null>(null);
  const voiceChunksRef = useRef<Blob[]>([]);
  const voiceStartedAtRef = useRef(0);
  const voiceTargetTimeRef = useRef(0);
  const voiceTargetFlagRef = useRef<ReplayFlag | null>(null);
  const voiceTargetClipIdRef = useRef("");
  const voicePlaybackTimerRef = useRef<number | null>(null);
  const lastTimeUpdateRef = useRef(0);
  const visibleAnnotationsRef = useRef<ReplayAnnotation[]>([]);
  const presentationRecorderRef = useRef<MediaRecorder | null>(null);
  const presentationChunksRef = useRef<Blob[]>([]);
  const presentationCleanupRef = useRef<(() => void) | null>(null);
  const presentationAnimationRef = useRef<number | null>(null);
  const presentationStartedAtRef = useRef(0);
  const presentationGenerationRef = useRef(0);
  const presentationMountedRef = useRef(false);
  const presentationDisposedRef = useRef(true);
  const presentationStartRequestRef = useRef(0);
  const presentationStartPendingRef = useRef(false);
  const presentationExportRequestRef = useRef(0);
  const presentationExportBusyRef = useRef(false);
  const [playbackUrl, setPlaybackUrl] = useState(video.url);
  const [currentMs, setCurrentMs] = useState(0);
  const [status, setStatus] = useState("");
  const [presentationRecording, setPresentationRecording] = useState(false);
  const [presentationStartPending, setPresentationStartPending] = useState(false);
  const [pendingPresentationExport, setPendingPresentationExport] = useState<ReplayPresentationRecordingPayload | null>(
    () => pendingReplayPresentationExports.get(replayId) ?? null
  );
  const [presentationPayloadPreparing, setPresentationPayloadPreparing] = useState(false);
  const [presentationExportBusy, setPresentationExportBusy] = useState(false);
  const [presentationStatus, setPresentationStatus] = useState(() => pendingReplayPresentationExports.has(replayId)
    ? "A presentation recording is ready to export."
    : ""
  );
  const [recordingVoice, setRecordingVoice] = useState(false);
  const [activeClipId, setActiveClipId] = useState<string | undefined>();
  const [activeClipStartedAt, setActiveClipStartedAt] = useState<number | undefined>();
  const [playbackClipId, setPlaybackClipId] = useState<string | undefined>();
  const [playbackOffsetMs, setPlaybackOffsetMs] = useState(0);
  const [voicePlaybackPaused, setVoicePlaybackPaused] = useState(false);
  const [replayAudioVolume, setReplayAudioVolume] = useState(0.9);
  const [replayAudioMuted, setReplayAudioMuted] = useState(false);
  const [videoFullscreen, setVideoFullscreen] = useState(false);
  const [videoPlaying, setVideoPlaying] = useState(false);
  const [playbackRate, setPlaybackRate] = useState<(typeof REPLAY_PLAYBACK_RATES)[number]>(1);
  const sortedFlags = [...flags].sort((a, b) => (a.timeMs ?? 0) - (b.timeMs ?? 0));
  const currentAnnotationTarget = `${video.path || video.url}:${Math.round(currentMs / 1000)}`;
  const visibleAnnotations = annotations.filter((annotation) =>
    (Boolean(annotation.clipId) && annotation.clipId === activeClipId)
      || (Boolean(annotation.clipId) && annotation.clipId === playbackClipId)
      || (!annotation.clipId && typeof annotation.timeMs === "number" && Math.abs(annotation.timeMs - currentMs) <= 1000)
  );
  const activeLayerFlags = sortedFlags.filter((flag) => replayLayerId(flag.layerId) === activeLayerId);
  const selectedFlagType = replayFlagSelectValue(flagType, flagCustomType, customFlagTypes);

  useEffect(() => {
    visibleAnnotationsRef.current = visibleAnnotations;
  }, [visibleAnnotations]);

  useEffect(() => {
    const retained = pendingReplayPresentationExports.get(replayId) ?? null;
    setPendingPresentationExport(retained);
    setPresentationPayloadPreparing(false);
    setPresentationExportBusy(false);
    setPresentationStatus(retained ? "A presentation recording is ready to export." : "");
  }, [replayId]);

  useEffect(() => {
    let cancelled = false;
    let objectUrl = "";
    setPlaybackUrl(video.url);
    setCurrentMs(0);
    setVideoPlaying(false);
    lastTimeUpdateRef.current = 0;
    if (!shouldBufferReplayVideoInMemory(video.sizeBytes)) {
      setStatus("Streaming replay from disk.");
      return () => undefined;
    }
    setStatus("Loading replay video for instant seeking...");
    void window.riftlite.loadReplayVideo(video)
      .then((buffer) => {
        if (cancelled) {
          return;
        }
        objectUrl = URL.createObjectURL(new Blob([buffer], { type: video.mimeType }));
        setPlaybackUrl(objectUrl);
        setStatus("");
      })
      .catch(() => {
        if (!cancelled) {
          setPlaybackUrl(video.url);
          setStatus("Using streamed playback fallback.");
        }
      });
    return () => {
      cancelled = true;
      if (objectUrl) {
        URL.revokeObjectURL(objectUrl);
      }
    };
  }, [video.path, video.url, video.mimeType, video.sizeBytes]);

  useEffect(() => {
    presentationMountedRef.current = true;
    presentationDisposedRef.current = false;
    deletedReplayPresentationIds.delete(replayId);
    presentationGenerationRef.current = nextReplayPresentationGeneration();
    replayPresentationDisposers.set(replayId, disposePresentationRuntime);
    return () => {
      presentationMountedRef.current = false;
      disposePresentationRuntime();
      if (replayPresentationDisposers.get(replayId) === disposePresentationRuntime) {
        replayPresentationDisposers.delete(replayId);
      }
      voiceRecorderRef.current?.state === "recording" && voiceRecorderRef.current.stop();
      voiceRecorderCleanupRef.current?.();
      audioRef.current?.pause();
      if (voicePlaybackTimerRef.current) {
        window.clearInterval(voicePlaybackTimerRef.current);
      }
      void window.riftlite.setWindowFullscreen(false).catch(() => undefined);
    };
  }, []);

  useEffect(() => {
    if (!videoFullscreen) {
      return;
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        void toggleVideoFullscreen(false);
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [videoFullscreen]);

  useEffect(() => {
    if (seekToMs == null || !videoRef.current) {
      return;
    }
    videoRef.current.currentTime = Math.max(0, seekToMs / 1000);
    videoRef.current.scrollIntoView({ block: "nearest", behavior: "smooth" });
    onSeekHandled();
  }, [seekToMs, onSeekHandled]);

  useEffect(() => {
    if (audioRef.current) {
      audioRef.current.volume = replayAudioMuted ? 0 : replayAudioVolume;
    }
    if (videoRef.current) {
      videoRef.current.volume = replayAudioVolume;
      videoRef.current.muted = replayAudioMuted;
    }
  }, [replayAudioMuted, replayAudioVolume]);

  useEffect(() => {
    if (videoRef.current) {
      videoRef.current.playbackRate = playbackRate;
    }
  }, [playbackRate, playbackUrl]);

  useEffect(() => {
    if (playbackClipId && !voiceNotes.some((note) => note.id === playbackClipId)) {
      stopVoicePlayback();
    }
  }, [playbackClipId, voiceNotes]);

  function nextPresentationStartRequest(): number {
    const requestId = presentationStartRequestRef.current >= Number.MAX_SAFE_INTEGER
      ? 1
      : presentationStartRequestRef.current + 1;
    presentationStartRequestRef.current = requestId;
    return requestId;
  }

  function nextPresentationExportRequest(): number {
    const requestId = presentationExportRequestRef.current >= Number.MAX_SAFE_INTEGER
      ? 1
      : presentationExportRequestRef.current + 1;
    presentationExportRequestRef.current = requestId;
    return requestId;
  }

  function isPresentationLifecycleCurrent(generation: number): boolean {
    return presentationMountedRef.current
      && !presentationDisposedRef.current
      && !deletedReplayPresentationIds.has(replayId)
      && presentationGenerationRef.current === generation
      && replayPresentationRecordingGeneration === generation;
  }

  function isPresentationStartCurrent(requestId: number, generation: number): boolean {
    return presentationStartRequestRef.current === requestId
      && isPresentationLifecycleCurrent(generation);
  }

  function cleanupPresentationRecording() {
    if (presentationAnimationRef.current !== null) {
      window.cancelAnimationFrame(presentationAnimationRef.current);
      presentationAnimationRef.current = null;
    }
    const cleanup = presentationCleanupRef.current;
    presentationCleanupRef.current = null;
    presentationRecorderRef.current = null;
    try {
      cleanup?.();
    } catch {
      // Refs are already cleared, so a platform cleanup error cannot orphan UI state.
    }
  }

  function disposePresentationRuntime(): void {
    presentationDisposedRef.current = true;
    presentationStartPendingRef.current = false;
    presentationExportBusyRef.current = false;
    nextPresentationStartRequest();
    nextPresentationExportRequest();
    presentationGenerationRef.current = nextReplayPresentationGeneration();
    const recorder = presentationRecorderRef.current;
    if (recorder) {
      recorder.ondataavailable = null;
      recorder.onstop = null;
      if (recorder.state !== "inactive") {
        try {
          recorder.requestData?.();
          recorder.stop();
        } catch {
          // The tracks are still stopped by cleanupPresentationRecording below.
        }
      }
    }
    presentationChunksRef.current = [];
    cleanupPresentationRecording();
  }

  function drawPresentationAnnotation(
    context: CanvasRenderingContext2D,
    annotation: ReplayAnnotation,
    width: number,
    height: number
  ) {
    const points = annotation.points.map((point) => ({
      x: point.x * width,
      y: point.y * height
    }));
    const first = points[0];
    const last = points.at(-1);
    if (!first) {
      return;
    }
    const strokeWidth = Math.max(4, annotation.width * 3 * (Math.min(width, height) / 1000));
    context.save();
    context.strokeStyle = annotation.color || "#6feeff";
    context.fillStyle = annotation.color || "#6feeff";
    context.lineWidth = strokeWidth;
    context.lineCap = "round";
    context.lineJoin = "round";
    context.globalAlpha = annotation.tool === "highlight" ? 0.48 : 0.94;
    if (annotation.tool === "text") {
      const text = annotation.text?.trim() || annotation.note?.trim() || "";
      context.globalAlpha = 1;
      context.font = `900 ${Math.max(34, Math.round(height * 0.046))}px Arial, sans-serif`;
      context.lineWidth = 10;
      context.strokeStyle = "#020712";
      context.strokeText(text, first.x, first.y);
      context.fillStyle = annotation.color || "#6feeff";
      context.fillText(text, first.x, first.y);
      context.restore();
      return;
    }
    if (annotation.tool === "arrow" && last) {
      context.beginPath();
      context.moveTo(first.x, first.y);
      context.lineTo(last.x, last.y);
      context.stroke();
      const angle = Math.atan2(last.y - first.y, last.x - first.x);
      const headLength = Math.max(16, strokeWidth * 3.2);
      context.beginPath();
      context.moveTo(last.x, last.y);
      context.lineTo(last.x - headLength * Math.cos(angle - Math.PI / 6), last.y - headLength * Math.sin(angle - Math.PI / 6));
      context.lineTo(last.x - headLength * Math.cos(angle + Math.PI / 6), last.y - headLength * Math.sin(angle + Math.PI / 6));
      context.closePath();
      context.fill();
      context.restore();
      return;
    }
    context.beginPath();
    points.forEach((point, index) => {
      if (index === 0) {
        context.moveTo(point.x, point.y);
      } else {
        context.lineTo(point.x, point.y);
      }
    });
    context.stroke();
    context.restore();
  }

  function drawPresentationFrame(
    canvas: HTMLCanvasElement,
    context: CanvasRenderingContext2D,
    track: (MediaStreamTrack & { requestFrame?: () => void }) | undefined,
    shouldContinue: () => boolean
  ) {
    if (!shouldContinue()) {
      return;
    }
    const element = videoRef.current;
    context.fillStyle = "#020814";
    context.fillRect(0, 0, canvas.width, canvas.height);
    if (element && element.readyState >= 2) {
      context.drawImage(element, 0, 0, canvas.width, canvas.height);
    }
    for (const annotation of visibleAnnotationsRef.current) {
      drawPresentationAnnotation(context, annotation, canvas.width, canvas.height);
    }
    track?.requestFrame?.();
    if (shouldContinue()) {
      presentationAnimationRef.current = window.requestAnimationFrame(() => {
        drawPresentationFrame(canvas, context, track, shouldContinue);
      });
    }
  }

  function retainPresentationExport(payload: ReplayPresentationRecordingPayload, generation: number): boolean {
    if (!isPresentationLifecycleCurrent(generation)) {
      return false;
    }
    pendingReplayPresentationExports.clear();
    pendingReplayPresentationExports.set(replayId, payload);
    setPendingPresentationExport(payload);
    return true;
  }

  function discardPendingPresentationExport(): void {
    if (
      presentationExportBusyRef.current
      || presentationPayloadPreparing
      || presentationStartPendingRef.current
      || presentationRecording
    ) {
      return;
    }
    nextPresentationStartRequest();
    nextPresentationExportRequest();
    presentationGenerationRef.current = nextReplayPresentationGeneration();
    pendingReplayPresentationExports.clear();
    setPendingPresentationExport(null);
    setPresentationStatus("Discarded the retained presentation recording.");
  }

  async function exportPendingPresentationRecording(
    payload: ReplayPresentationRecordingPayload | null = pendingPresentationExport
  ): Promise<void> {
    const generation = presentationGenerationRef.current;
    if (
      !payload
      || presentationExportBusyRef.current
      || presentationPayloadPreparing
      || !isPresentationLifecycleCurrent(generation)
    ) {
      return;
    }
    const exportRequestId = nextPresentationExportRequest();
    presentationExportBusyRef.current = true;
    setPresentationExportBusy(true);
    setPresentationStatus("Choose where to save the retained presentation MP4...");
    try {
      const outputPath = await onExportPresentationMp4(replayId, payload);
      const clearedRetainedPayload = Boolean(
        outputPath && pendingReplayPresentationExports.get(replayId) === payload
      );
      if (clearedRetainedPayload) {
        // The main process only resolves with a path after validation and promotion.
        // Clear the retained bytes even if this player unmounted while export ran.
        pendingReplayPresentationExports.delete(replayId);
      }
      if (
        presentationExportRequestRef.current !== exportRequestId
        || !isPresentationLifecycleCurrent(generation)
      ) {
        return;
      }
      if (!outputPath) {
        setPresentationStatus("Presentation export cancelled. The recording is kept here so you can retry.");
        return;
      }
      if (clearedRetainedPayload) {
        setPendingPresentationExport(null);
      }
      setPresentationStatus(`Presentation MP4 exported to ${outputPath}`);
    } catch (error) {
      if (
        presentationExportRequestRef.current === exportRequestId
        && isPresentationLifecycleCurrent(generation)
      ) {
        const message = rendererErrorMessage(error, "Presentation export failed.");
        setPresentationStatus(`${message} The recording is kept here so you can retry.`);
      }
    } finally {
      if (presentationExportRequestRef.current === exportRequestId) {
        presentationExportBusyRef.current = false;
        if (isPresentationLifecycleCurrent(generation)) {
          setPresentationExportBusy(false);
        }
      }
    }
  }

  async function startPresentationRecording() {
    if (
      presentationExportBusyRef.current
      || presentationPayloadPreparing
      || presentationStartPendingRef.current
      || presentationRecorderRef.current
      || presentationRecording
      || !presentationMountedRef.current
      || presentationDisposedRef.current
      || deletedReplayPresentationIds.has(replayId)
    ) {
      return;
    }
    const element = videoRef.current;
    if (!element || !element.videoWidth || !element.videoHeight) {
      setPresentationStatus("Replay video is not ready yet.");
      return;
    }
    if (typeof MediaRecorder === "undefined" || typeof HTMLCanvasElement.prototype.captureStream !== "function") {
      setPresentationStatus("Presentation recording is not available on this system.");
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia) {
      setPresentationStatus("Microphone access is not available on this system.");
      return;
    }
    const canvas = document.createElement("canvas");
    canvas.width = Math.max(2, element.videoWidth - (element.videoWidth % 2));
    canvas.height = Math.max(2, element.videoHeight - (element.videoHeight % 2));
    const context = canvas.getContext("2d", { alpha: false });
    if (!context) {
      setPresentationStatus("Could not create presentation canvas.");
      return;
    }

    // This token is captured before the microphone permission await. It serializes
    // rapid clicks and makes every continuation conditional on this mounted replay.
    const startRequestId = nextPresentationStartRequest();
    const generation = nextReplayPresentationGeneration();
    presentationGenerationRef.current = generation;
    presentationStartPendingRef.current = true;
    setPresentationStartPending(true);
    nextPresentationExportRequest();
    // Keep any retained recording until microphone access succeeds and the new
    // MediaRecorder has actually started, so a denied prompt cannot destroy it.
    setPresentationStatus("Waiting for microphone access before recording...");
    let acquiredResourceCleanup: (() => void) | null = null;
    try {
      stopVoicePlayback();
      if (recordingVoice) {
        stopTimelineVoiceNote();
      }
      const voiceCapture = await createVoiceStreamCapture(microphoneDeviceId);
      let voiceCaptureCleaned = false;
      const cleanupVoiceCapture = () => {
        if (voiceCaptureCleaned) {
          return;
        }
        voiceCaptureCleaned = true;
        voiceCapture.stream.getTracks().forEach((track) => track.stop());
        voiceCapture.cleanup();
      };
      acquiredResourceCleanup = cleanupVoiceCapture;
      if (!isPresentationStartCurrent(startRequestId, generation)) {
        acquiredResourceCleanup();
        acquiredResourceCleanup = null;
        return;
      }
      const fps = Math.min(30, Math.max(15, video.fps || 24));
      const canvasStream = canvas.captureStream(fps);
      const canvasTrack = canvasStream.getVideoTracks()[0] as MediaStreamTrack & { requestFrame?: () => void };
      const combinedStream = new MediaStream([
        ...canvasStream.getVideoTracks(),
        ...voiceCapture.stream.getAudioTracks()
      ]);
      let recordingResourcesCleaned = false;
      const cleanupRecordingResources = () => {
        if (recordingResourcesCleaned) {
          return;
        }
        recordingResourcesCleaned = true;
        combinedStream.getTracks().forEach((track) => track.stop());
        canvasStream.getTracks().forEach((track) => track.stop());
        cleanupVoiceCapture();
      };
      acquiredResourceCleanup = cleanupRecordingResources;
      const mimeCandidates = [
        "video/webm;codecs=vp9,opus",
        "video/webm;codecs=vp8,opus",
        "video/webm"
      ];
      const mimeType = mimeCandidates.find((candidate) => MediaRecorder.isTypeSupported(candidate)) ?? "";
      const recorder = new MediaRecorder(combinedStream, {
        ...(mimeType ? { mimeType } : {}),
        videoBitsPerSecond: 8_000_000,
        audioBitsPerSecond: 160_000
      });
      presentationChunksRef.current = [];
      presentationStartedAtRef.current = Date.now();
      presentationRecorderRef.current = recorder;
      presentationCleanupRef.current = cleanupRecordingResources;
      acquiredResourceCleanup = null;
      const recordingIsCurrent = () => isPresentationStartCurrent(startRequestId, generation);
      recorder.ondataavailable = (event) => {
        if (recordingIsCurrent() && event.data.size) {
          presentationChunksRef.current.push(event.data);
        }
      };
      recorder.onstop = () => {
        const recordingIsStillCurrent = recordingIsCurrent();
        const durationMs = Math.max(0, Date.now() - presentationStartedAtRef.current);
        const chunks = recordingIsStillCurrent ? presentationChunksRef.current : [];
        const blob = new Blob(chunks, { type: recorder.mimeType || "video/webm" });
        presentationChunksRef.current = [];
        cleanupPresentationRecording();
        if (!recordingIsStillCurrent) {
          return;
        }
        setPresentationRecording(false);
        if (!blob.size) {
          setPresentationStatus("No presentation video was captured.");
          return;
        }
        setPresentationStatus("Securing presentation recording for export...");
        setPresentationPayloadPreparing(true);
        void blob.arrayBuffer()
          .then((data) => {
            if (!recordingIsCurrent()) {
              return;
            }
            const payload: ReplayPresentationRecordingPayload = {
              data,
              mimeType: blob.type || "video/webm",
              durationMs
            };
            if (!retainPresentationExport(payload, generation)) {
              return;
            }
            setPresentationPayloadPreparing(false);
            setPresentationStatus("Presentation recording retained. Choose a save location for the MP4.");
            void exportPendingPresentationRecording(payload);
          })
          .catch((error) => {
            if (recordingIsCurrent()) {
              setPresentationPayloadPreparing(false);
              setPresentationStatus(rendererErrorMessage(error, "The presentation recording could not be prepared for export."));
            }
          });
      };
      drawPresentationFrame(canvas, context, canvasTrack, recordingIsCurrent);
      recorder.start(1000);
      // Choosing Record new explicitly replaces the one retained app-wide recording
      // only after the replacement is known to be recording successfully.
      pendingReplayPresentationExports.clear();
      setPendingPresentationExport(null);
      if (recordingIsCurrent()) {
        setPresentationRecording(true);
        setPresentationStatus("Presentation recording. Play, pause, draw, and talk; stop to export one MP4.");
      }
    } catch (error) {
      acquiredResourceCleanup?.();
      cleanupPresentationRecording();
      presentationChunksRef.current = [];
      if (isPresentationStartCurrent(startRequestId, generation)) {
        setPresentationRecording(false);
        setPresentationStatus(rendererErrorMessage(error, "Presentation recording could not start."));
      }
    } finally {
      if (presentationStartRequestRef.current === startRequestId) {
        presentationStartPendingRef.current = false;
        if (presentationMountedRef.current && !presentationDisposedRef.current) {
          setPresentationStartPending(false);
        }
      }
    }
  }

  function stopPresentationRecording() {
    if (presentationRecorderRef.current?.state === "recording") {
      setPresentationStatus("Finalising presentation recording...");
      presentationRecorderRef.current.requestData?.();
      presentationRecorderRef.current.stop();
    }
  }

  function clearVisiblePresentationDrawings() {
    const ids = visibleAnnotationsRef.current.map((annotation) => annotation.id);
    if (!ids.length) {
      setPresentationStatus("No visible drawings to clear.");
      return;
    }
    onRemoveAnnotations(ids);
    setPresentationStatus("Cleared visible drawings.");
  }

  async function saveKeyframe() {
    const element = videoRef.current;
    if (!element || !element.videoWidth || !element.videoHeight) {
      setStatus("Video frame is not ready yet.");
      return;
    }
    const canvas = document.createElement("canvas");
    canvas.width = element.videoWidth;
    canvas.height = element.videoHeight;
    const context = canvas.getContext("2d", { alpha: false });
    if (!context) {
      return;
    }
    context.drawImage(element, 0, 0, canvas.width, canvas.height);
    setStatus("Saving keyframe...");
    await onSaveKeyframe(canvas.toDataURL("image/jpeg", 0.82), currentMs);
    setStatus(`Saved keyframe at ${formatDuration(currentMs)}.`);
  }

  function startVoicePlaybackTimer() {
    if (voicePlaybackTimerRef.current) {
      window.clearInterval(voicePlaybackTimerRef.current);
    }
    voicePlaybackTimerRef.current = window.setInterval(() => {
      setPlaybackOffsetMs(Math.round((audioRef.current?.currentTime ?? 0) * 1000));
    }, 80);
  }

  function stopVoicePlayback() {
    if (voicePlaybackTimerRef.current) {
      window.clearInterval(voicePlaybackTimerRef.current);
      voicePlaybackTimerRef.current = null;
    }
    audioRef.current?.pause();
    setPlaybackClipId(undefined);
    setPlaybackOffsetMs(0);
    setVoicePlaybackPaused(false);
  }

  function playVoiceNote(note: ReplayVoiceNote, flag?: ReplayFlag) {
    if (!audioRef.current) {
      audioRef.current = new Audio();
    }
    stopVoicePlayback();
    audioRef.current.pause();
    audioRef.current.src = note.dataUrl;
    audioRef.current.currentTime = 0;
    audioRef.current.volume = replayAudioMuted ? 0 : replayAudioVolume;
    if (videoRef.current && typeof flag?.timeMs === "number") {
      videoRef.current.currentTime = Math.max(0, flag.timeMs / 1000);
      setCurrentMs(flag.timeMs);
      videoRef.current.pause();
    }
    setPlaybackClipId(note.id);
    setPlaybackOffsetMs(0);
    setVoicePlaybackPaused(false);
    startVoicePlaybackTimer();
    audioRef.current.onended = () => stopVoicePlayback();
    audioRef.current.onpause = () => {
      if (audioRef.current?.ended) {
        stopVoicePlayback();
      }
    };
    void audioRef.current.play().catch(() => setStatus("Could not play voice note."));
  }

  function pauseVoicePlayback() {
    if (!audioRef.current || !playbackClipId) {
      return;
    }
    audioRef.current.pause();
    if (voicePlaybackTimerRef.current) {
      window.clearInterval(voicePlaybackTimerRef.current);
      voicePlaybackTimerRef.current = null;
    }
    setVoicePlaybackPaused(true);
    setStatus(`Voice note paused at ${formatDuration(playbackOffsetMs)}.`);
  }

  function resumeVoicePlayback() {
    if (!audioRef.current || !playbackClipId) {
      return;
    }
    startVoicePlaybackTimer();
    setVoicePlaybackPaused(false);
    void audioRef.current.play().catch(() => setStatus("Could not resume voice note."));
  }

  async function toggleVideoFullscreen(force?: boolean) {
    const enabled = force ?? !videoFullscreen;
    setVideoFullscreen(enabled);
    try {
      await window.riftlite.setWindowFullscreen(enabled);
      setStatus(enabled ? "Replay full screen. Press Esc or the button to exit." : "");
    } catch {
      setStatus("Native fullscreen was blocked, using in-app fullscreen.");
    }
  }

  function toggleVideoPlayback() {
    const element = videoRef.current;
    if (!element) {
      return;
    }
    if (recordingVoice || playbackClipId) {
      element.pause();
      return;
    }
    if (element.paused) {
      void element.play().catch(() => setStatus("Could not start replay playback."));
    } else {
      element.pause();
    }
  }

  function seekVideo(timeMs: number) {
    const nextMs = Math.min(Math.max(0, timeMs), Math.max(0, video.durationMs || 0));
    if (videoRef.current) {
      videoRef.current.currentTime = nextMs / 1000;
    }
    setCurrentMs(nextMs);
    onTimeChange(nextMs);
    lastTimeUpdateRef.current = nextMs;
  }

  function skipVideo(deltaMs: number) {
    const baseMs = videoRef.current ? Math.round(videoRef.current.currentTime * 1000) : currentMs;
    seekVideo(baseMs + deltaMs);
  }

  function timelineFlagForVoice(timeMs: number): ReplayFlag {
    const nearby = activeLayerFlags.find((flag) =>
      typeof flag.timeMs === "number" && Math.abs(flag.timeMs - timeMs) <= 1500
    );
    if (nearby) {
      return nearby;
    }
    return {
      id: crypto.randomUUID(),
      targetType: "video-time",
      targetId: `${video.path || video.url}:${Math.round(timeMs)}`,
      targetLabel: `Video ${formatDuration(timeMs)}`,
      type: "key-turn",
      layerId: activeLayerId,
      label: "Key turn",
      note: "",
      capturedAt: replayVideoCapturedAt(video, timeMs),
      createdAt: new Date().toISOString(),
      timeMs
    };
  }

  async function startTimelineVoiceNote() {
    if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === "undefined") {
      setStatus("Voice recording is not available on this system.");
      return;
    }
    try {
      videoRef.current?.pause();
      const capture = await createVoiceRecorderCapture(microphoneDeviceId);
      const recorder = capture.recorder;
      voiceChunksRef.current = [];
      voiceRecorderCleanupRef.current = capture.cleanup;
      voiceRecorderRef.current = recorder;
      voiceStartedAtRef.current = Date.now();
      voiceTargetTimeRef.current = currentMs;
      voiceTargetFlagRef.current = timelineFlagForVoice(currentMs);
      voiceTargetClipIdRef.current = replayVoiceNoteForFlag(voiceNotes, voiceTargetFlagRef.current.id, activeLayerId)?.id ?? crypto.randomUUID();
      recorder.ondataavailable = (event) => {
        if (event.data.size) {
          voiceChunksRef.current.push(event.data);
        }
      };
      recorder.onstop = () => {
        const targetTimeMs = voiceTargetTimeRef.current;
        const durationMs = Date.now() - voiceStartedAtRef.current;
        const blob = new Blob(voiceChunksRef.current, { type: recorder.mimeType || "audio/webm" });
        const flag = voiceTargetFlagRef.current ?? timelineFlagForVoice(targetTimeMs);
        const clipId = voiceTargetClipIdRef.current || replayVoiceNoteForFlag(voiceNotes, flag.id, activeLayerId)?.id || crypto.randomUUID();
        voiceRecorderCleanupRef.current?.();
        voiceRecorderCleanupRef.current = null;
        voiceRecorderRef.current = null;
        voiceTargetFlagRef.current = null;
        voiceTargetClipIdRef.current = "";
        setRecordingVoice(false);
        setActiveClipId(undefined);
        setActiveClipStartedAt(undefined);
        if (!blob.size) {
          setStatus("No voice note was captured.");
          return;
        }
        void blobToDataUrl(blob)
          .then((dataUrl) => {
            onSaveTimelineVoiceNote(flag, {
              id: clipId,
              flagId: flag.id,
              layerId: activeLayerId,
              mimeType: blob.type || "audio/webm",
              dataUrl,
              durationMs,
              sizeBytes: blob.size,
              createdAt: new Date().toISOString(),
              updatedAt: new Date().toISOString()
            });
            setStatus(`Saved voice note at ${formatDuration(targetTimeMs)}.`);
          })
          .catch(() => setStatus("Could not save voice note."));
      };
      recorder.start();
      setRecordingVoice(true);
      setActiveClipId(voiceTargetClipIdRef.current);
      setActiveClipStartedAt(voiceStartedAtRef.current);
      setStatus(`Recording coaching note at ${formatDuration(currentMs)}. Draw now to sync marks to this audio.`);
    } catch (error) {
      setRecordingVoice(false);
      setActiveClipId(undefined);
      setActiveClipStartedAt(undefined);
      voiceRecorderCleanupRef.current?.();
      voiceRecorderCleanupRef.current = null;
      setStatus(error instanceof Error ? error.message : "Microphone access was blocked.");
    }
  }

  function stopTimelineVoiceNote() {
    if (voiceRecorderRef.current?.state === "recording") {
      voiceRecorderRef.current.stop();
    }
  }

  return (
    <section className={`rail-card replay-video-panel ${videoFullscreen ? "replay-video-fullscreen" : ""}`} data-fullscreen={videoFullscreen}>
      <header>
        <div>
          <h2>Video replay</h2>
          <span>{REPLAY_VIDEO_PROFILES[video.quality]?.label ?? video.quality} - {formatDuration(video.durationMs)} - {formatBytes(video.sizeBytes)}</span>
        </div>
        <div className="row-actions">
          <button
            type="button"
            className={presentationRecording ? "danger" : pendingPresentationExport ? "primary" : "secondary"}
            onClick={() => presentationRecording
              ? stopPresentationRecording()
              : pendingPresentationExport
                ? void exportPendingPresentationRecording()
                : void startPresentationRecording()
            }
            disabled={Boolean(playbackClipId) || presentationExportBusy || presentationPayloadPreparing || presentationStartPending}
            title={pendingPresentationExport
              ? "Retry saving the retained presentation recording as a validated MP4"
              : "Record replay playback, pauses, drawings, and microphone narration into one MP4"
            }
          >
            {pendingPresentationExport ? <RefreshCw size={14} /> : <Video size={14} />}
            {presentationRecording
              ? "Stop presentation"
              : presentationPayloadPreparing
                ? "Securing recording..."
                : presentationStartPending
                  ? "Waiting for microphone..."
                : presentationExportBusy
                  ? "Exporting presentation..."
                  : pendingPresentationExport
                    ? "Retry presentation export"
                    : "Presentation MP4"
            }
          </button>
          {pendingPresentationExport && !presentationRecording ? (
            <>
              <button
                type="button"
                className="secondary"
                disabled={presentationExportBusy || presentationPayloadPreparing || presentationStartPending || Boolean(playbackClipId)}
                onClick={() => void startPresentationRecording()}
                title="Explicitly replace the retained recording with a new presentation"
              >
                <Video size={14} /> Record new
              </button>
              <button
                type="button"
                className="secondary danger"
                disabled={presentationExportBusy || presentationPayloadPreparing || presentationStartPending}
                onClick={discardPendingPresentationExport}
                title="Discard the retained presentation recording"
              >
                <Trash2 size={14} /> Discard recording
              </button>
            </>
          ) : null}
          <button
            type="button"
            className="secondary"
            onClick={clearVisiblePresentationDrawings}
            disabled={!visibleAnnotations.length}
            title="Clear drawings visible at the current replay timestamp"
          >
            <Trash2 size={14} /> Clear drawing
          </button>
          <button type="button" className={recordingVoice ? "danger" : "secondary"} onClick={() => recordingVoice ? stopTimelineVoiceNote() : void startTimelineVoiceNote()}>
            <Mic size={14} /> {recordingVoice ? "Stop coaching note" : "Record coaching note"}
          </button>
          {playbackClipId ? (
            <button type="button" className="secondary" onClick={() => voicePlaybackPaused ? resumeVoicePlayback() : pauseVoicePlayback()}>
              {voicePlaybackPaused ? <Play size={14} /> : <Pause size={14} />} {voicePlaybackPaused ? "Resume voice" : "Pause voice"}
            </button>
          ) : null}
          <label className="replay-voice-volume" title="Replay and coaching audio volume">
            <button
              type="button"
              className="replay-audio-mute"
              onClick={() => setReplayAudioMuted((muted) => !muted)}
              title={replayAudioMuted ? "Unmute replay audio" : "Mute replay audio"}
              aria-label={replayAudioMuted ? "Unmute replay audio" : "Mute replay audio"}
            >
              {replayAudioMuted || replayAudioVolume <= 0 ? <VolumeX size={14} /> : <Volume2 size={14} />}
            </button>
            <input
              type="range"
              min="0"
              max="1"
              step="0.05"
              value={replayAudioMuted ? 0 : replayAudioVolume}
              onChange={(event) => {
                const next = Number.parseFloat(event.target.value) || 0;
                setReplayAudioVolume(next);
                setReplayAudioMuted(next <= 0);
              }}
            />
            <span>{replayAudioMuted ? "Muted" : `${Math.round(replayAudioVolume * 100)}%`}</span>
          </label>
          {videoFullscreen ? (
            <>
              <button type="button" className="secondary" onClick={() => skipVideo(-20000)} title="Go back 20 seconds">
                <RotateCcw size={14} /> Back 20s
              </button>
              <button type="button" className="secondary" onClick={() => skipVideo(20000)} title="Go forward 20 seconds">
                <RotateCw size={14} /> Forward 20s
              </button>
            </>
          ) : null}
          <button type="button" className="secondary" onClick={() => void toggleVideoFullscreen()}>
            <Maximize2 size={14} /> {videoFullscreen ? "Exit full screen" : "Full screen"}
          </button>
          <button type="button" className="secondary" onClick={() => onClip(currentMs)}>
            <Scissors size={14} /> Clip
          </button>
          <button type="button" className="secondary" onClick={() => void saveKeyframe()}><Save size={14} /> Save keyframe</button>
        </div>
      </header>
      <div className="replay-video-quick-flag">
        <label>
          Type
          <select value={selectedFlagType} onChange={(event) => onFlagTypeSelect(event.target.value)}>
            {replayFlagTypeOptions(customFlagTypes).map((type) => (
              <option value={type.value} key={type.value}>{type.label}</option>
            ))}
          </select>
        </label>
        {flagType === "custom" ? (
          <label>
            Custom label
            <input value={flagCustomType} onChange={(event) => onFlagCustomTypeChange(event.target.value)} placeholder="Question, alternative line..." />
          </label>
        ) : null}
        <label className="replay-video-quick-note">
          Note
          <input value={flagNote} onChange={(event) => onFlagNoteChange(event.target.value)} placeholder="Optional note for this timestamp..." />
        </label>
        <div className="row-actions">
          {flagType === "custom" ? (
            <button type="button" className="secondary" onClick={onRememberCustomType} disabled={!flagCustomType.trim()}>
              <Plus size={14} /> Save type
            </button>
          ) : null}
          <button type="button" className="primary" onClick={() => onFlagTime(currentMs)}>
            <Flag size={14} /> Flag {formatDuration(currentMs)}
          </button>
        </div>
      </div>
      {recordingVoice ? (
        <div className="replay-coaching-status" data-state="recording">
          <Mic size={15} />
          <strong>Recording synced coaching note</strong>
          <span>The replay is paused. Draw, arrow, highlight, or add text now and it will replay with this audio.</span>
        </div>
      ) : presentationRecording ? (
        <div className="replay-coaching-status" data-state="presentation">
          <Video size={15} />
          <strong>Recording presentation MP4</strong>
          <span>Play, pause, draw, and talk. Stop recording to export one continuous video.</span>
        </div>
      ) : pendingPresentationExport ? (
        <div className="replay-coaching-status" data-state="ready" role="status">
          <Check size={15} />
          <strong>Presentation recording retained</strong>
          <span>{formatDuration(pendingPresentationExport.durationMs)} · {formatBytes(pendingPresentationExport.data.byteLength)}. Retry export, record a replacement, or discard it explicitly.</span>
        </div>
      ) : playbackClipId ? (
        <div className="replay-coaching-status" data-state="playing">
          <Mic size={15} />
          <strong>Playing coaching note</strong>
          <span>Synced drawings appear as the audio reaches them.</span>
        </div>
      ) : null}
      <div className="replay-video-stage" ref={videoStageRef}>
        <video
          ref={videoRef}
          src={playbackUrl}
          controls={false}
          disablePictureInPicture
          preload="auto"
          onClick={toggleVideoPlayback}
          onDoubleClick={() => void toggleVideoFullscreen()}
          onPlay={(event) => {
            if (recordingVoice || playbackClipId) {
              event.currentTarget.pause();
              setVideoPlaying(false);
              return;
            }
            setVideoPlaying(true);
          }}
          onPause={() => setVideoPlaying(false)}
          onEnded={() => setVideoPlaying(false)}
          onLoadedMetadata={(event) => {
            const nextMs = Math.round(event.currentTarget.currentTime * 1000);
            event.currentTarget.playbackRate = playbackRate;
            event.currentTarget.volume = replayAudioVolume;
            event.currentTarget.muted = replayAudioMuted;
            setCurrentMs(nextMs);
            onTimeChange(nextMs);
          }}
          onTimeUpdate={(event) => {
            const nextMs = Math.round(event.currentTarget.currentTime * 1000);
            if (Math.abs(nextMs - lastTimeUpdateRef.current) >= 500) {
              lastTimeUpdateRef.current = nextMs;
              setCurrentMs(nextMs);
              onTimeChange(nextMs);
            }
          }}
        />
        <ReplayAnnotationCanvas
          annotations={visibleAnnotations}
          targetId={currentAnnotationTarget}
          targetLabel={`Video ${formatDuration(currentMs)}`}
          capturedAt={replayVideoCapturedAt(video, currentMs)}
          timeMs={currentMs}
          layerId={activeLayerId}
          activeClipId={activeClipId}
          activeClipStartedAt={activeClipStartedAt}
          playbackClipId={playbackClipId}
          playbackOffsetMs={playbackOffsetMs}
          onAddAnnotation={onAddAnnotation}
          onRemoveAnnotation={onRemoveAnnotation}
          onRemoveAnnotations={onRemoveAnnotations}
        />
      </div>
      <div className="replay-video-controls">
        <button type="button" className="secondary replay-video-skip-button" onClick={() => skipVideo(-20000)} title="Go back 20 seconds">
          <RotateCcw size={15} /> 20s
        </button>
        <button type="button" className="secondary" onClick={toggleVideoPlayback} disabled={recordingVoice || Boolean(playbackClipId)}>
          {videoPlaying ? <Pause size={15} /> : <Play size={15} />} {videoPlaying ? "Pause" : "Play"}
        </button>
        <div className="replay-playback-rate" role="group" aria-label="Replay playback speed">
          {REPLAY_PLAYBACK_RATES.map((rate) => (
            <button
              type="button"
              key={rate}
              className="secondary replay-rate-button"
              data-active={playbackRate === rate}
              onClick={() => setPlaybackRate(rate)}
              title={`Play replay at ${rate}x speed`}
            >
              {rate}x
            </button>
          ))}
        </div>
        <label>
          <span>{formatDuration(currentMs)}</span>
          <input
            type="range"
            min="0"
            max={Math.max(1, video.durationMs || 1)}
            step="250"
            value={Math.min(currentMs, Math.max(1, video.durationMs || 1))}
            onChange={(event) => seekVideo(Number.parseInt(event.target.value, 10) || 0)}
          />
          <span>{formatDuration(video.durationMs || 0)}</span>
        </label>
        <button type="button" className="secondary replay-video-skip-button" onClick={() => skipVideo(20000)} title="Go forward 20 seconds">
          <RotateCw size={15} /> 20s
        </button>
        <button type="button" className="secondary" onClick={() => void toggleVideoFullscreen()}>
          <Maximize2 size={15} /> {videoFullscreen ? "Exit full screen" : "Full screen"}
        </button>
        <button type="button" className="secondary" onClick={() => onClip(currentMs)}>
          <Scissors size={15} /> Clip
        </button>
      </div>
      <ReplayVideoMarkerTimeline
        video={video}
        flags={sortedFlags}
        voiceNotes={voiceNotes}
        intelligenceEvents={intelligenceEvents}
        currentMs={currentMs}
        playbackClipId={playbackClipId}
        voicePlaybackPaused={voicePlaybackPaused}
        onSeek={seekVideo}
        onPlayVoice={playVoiceNote}
        onPauseVoice={pauseVoicePlayback}
        onResumeVoice={resumeVoicePlayback}
        onEditFlag={onEditFlag}
      />
      <div className="replay-video-meta">
        <span>{video.width}x{video.height}</span>
        <span>{video.fps} fps</span>
        <span>{video.actualBitrateKbps ? `${video.actualBitrateKbps} kbps actual` : `${video.bitrateKbps} kbps target`}</span>
        <span>{video.codec || video.mimeType}</span>
        <span>{video.source === "riftreplay" ? "Imported replay video" : video.source.replace(/-/g, " ")}</span>
      </div>
      {sortedFlags.length ? (
        <div className="replay-video-flags">
          {sortedFlags.map((flag) => (
            <button
              type="button"
              key={flag.id}
              title="Click to jump, right-click to edit this flag"
              onClick={() => {
                if (videoRef.current && typeof flag.timeMs === "number") {
                  videoRef.current.currentTime = flag.timeMs / 1000;
                  setCurrentMs(flag.timeMs);
                  onTimeChange(flag.timeMs);
                }
              }}
              onContextMenu={(event) => {
                event.preventDefault();
                onEditFlag(flag);
              }}
            >
              <strong>{formatDuration(flag.timeMs ?? 0)}</strong>
              <span>{replayFlagTypeLabel(flag)}{flag.note ? ` - ${flag.note}` : ""}</span>
            </button>
          ))}
        </div>
      ) : null}
      {presentationStatus ? <p className="muted replay-presentation-status" role="status" aria-live="polite">{presentationStatus}</p> : null}
      {status ? <p className="muted">{status}</p> : null}
    </section>
  );
}

function ReplayVideoMarkerTimeline({
  video,
  flags,
  voiceNotes,
  intelligenceEvents,
  currentMs,
  playbackClipId,
  voicePlaybackPaused,
  onSeek,
  onPlayVoice,
  onPauseVoice,
  onResumeVoice,
  onEditFlag
}: {
  video: ReplayVideoAsset;
  flags: ReplayFlag[];
  voiceNotes: ReplayVoiceNote[];
  intelligenceEvents: ReplayIntelligenceEvent[];
  currentMs: number;
  playbackClipId?: string;
  voicePlaybackPaused: boolean;
  onSeek: (timeMs: number) => void;
  onPlayVoice: (note: ReplayVoiceNote, flag: ReplayFlag) => void;
  onPauseVoice: () => void;
  onResumeVoice: () => void;
  onEditFlag: (flag: ReplayFlag) => void;
}) {
  const durationMs = Math.max(1, video.durationMs || 1);
  const sortedFlags = [...flags].filter((flag) => typeof flag.timeMs === "number").sort((a, b) => (a.timeMs ?? 0) - (b.timeMs ?? 0));
  const intelligencePins = intelligenceEvents
    .filter((event) => typeof event.videoTimeMs === "number" && ["mulligan", "play", "combat", "score", "battlefield", "result"].includes(event.type))
    .filter((event, index, all) => all.findIndex((item) => Math.abs((item.videoTimeMs ?? 0) - (event.videoTimeMs ?? 0)) < 1_500 && item.type === event.type) === index)
    .slice(0, 80);
  const seekFromPointer = (event: React.PointerEvent<HTMLDivElement>) => {
    const rect = event.currentTarget.getBoundingClientRect();
    if (!rect.width) {
      return;
    }
    const offset = Math.min(Math.max(0, event.clientX - rect.left), rect.width);
    onSeek((offset / rect.width) * durationMs);
  };
  return (
    <div className="replay-marker-timeline">
      <div
        className="replay-marker-rail"
        role="slider"
        tabIndex={0}
        aria-label="Replay timeline"
        aria-valuemin={0}
        aria-valuemax={Math.round(durationMs / 1000)}
        aria-valuenow={Math.round(currentMs / 1000)}
        aria-valuetext={`${formatDuration(currentMs)} of ${formatDuration(durationMs)}`}
        onPointerDown={(event) => {
          const target = event.target as HTMLElement | null;
          if (target?.closest(".replay-marker-pin")) {
            return;
          }
          event.currentTarget.setPointerCapture(event.pointerId);
          seekFromPointer(event);
        }}
        onPointerMove={(event) => {
          if (event.currentTarget.hasPointerCapture(event.pointerId)) {
            seekFromPointer(event);
          }
        }}
        onPointerUp={(event) => {
          if (event.currentTarget.hasPointerCapture(event.pointerId)) {
            event.currentTarget.releasePointerCapture(event.pointerId);
          }
        }}
        onPointerCancel={(event) => {
          if (event.currentTarget.hasPointerCapture(event.pointerId)) {
            event.currentTarget.releasePointerCapture(event.pointerId);
          }
        }}
        onKeyDown={(event) => {
          if (event.key === "ArrowLeft") {
            event.preventDefault();
            onSeek(currentMs - 5000);
          } else if (event.key === "ArrowRight") {
            event.preventDefault();
            onSeek(currentMs + 5000);
          } else if (event.key === "Home") {
            event.preventDefault();
            onSeek(0);
          } else if (event.key === "End") {
            event.preventDefault();
            onSeek(durationMs);
          }
        }}
      >
        <span className="replay-marker-progress" style={{ width: `${Math.min(100, Math.max(0, (currentMs / durationMs) * 100))}%` }} />
        {intelligencePins.map((event) => {
          const left = Math.min(100, Math.max(0, ((event.videoTimeMs ?? 0) / durationMs) * 100));
          return (
            <button
              type="button"
              className="replay-intelligence-marker-pin"
              data-event-type={event.type}
              data-confidence={event.confidence}
              style={{ left: `${left}%` }}
              key={`intelligence:${event.id}`}
              title={`${event.type.replace("-", " ")} · ${event.text} · ${event.confidence}`}
              onClick={() => onSeek(event.videoTimeMs ?? 0)}
              onPointerDown={(pointerEvent) => pointerEvent.stopPropagation()}
            />
          );
        })}
        {sortedFlags.map((flag) => {
          const note = replayVoiceNoteForFlag(voiceNotes, flag.id, flag.layerId);
          const isPlayingNote = Boolean(note && playbackClipId === note.id);
          const left = Math.min(100, Math.max(0, ((flag.timeMs ?? 0) / durationMs) * 100));
          return (
            <button
              type="button"
              className="replay-marker-pin"
              data-flag-type={flag.type ?? replayFlagTypeFromLabel(flag.label)}
              data-has-voice={Boolean(note)}
              data-playing={isPlayingNote}
              style={{ left: `${left}%` }}
              key={flag.id}
              title={`${replayFlagTypeLabel(flag)}${note ? " - voice note" : ""}. Click to jump${note ? " and play/pause" : ""}; right-click to edit.`}
              onClick={() => {
                if (isPlayingNote) {
                  if (voicePlaybackPaused) {
                    onResumeVoice();
                  } else {
                    onPauseVoice();
                  }
                  return;
                }
                onSeek(flag.timeMs ?? 0);
                if (note) {
                  onPlayVoice(note, flag);
                }
              }}
              onPointerDown={(event) => event.stopPropagation()}
              onContextMenu={(event) => {
                event.preventDefault();
                onEditFlag(flag);
              }}
            >
              {isPlayingNote ? (voicePlaybackPaused ? <Play size={13} /> : <Pause size={13} />) : note ? <Mic size={13} /> : <Flag size={13} />}
            </button>
          );
        })}
      </div>
      <div className="replay-marker-chips">
        {sortedFlags.map((flag) => {
          const note = replayVoiceNoteForFlag(voiceNotes, flag.id, flag.layerId);
          const isPlayingNote = Boolean(note && playbackClipId === note.id);
          return (
            <button
              type="button"
              key={`${flag.id}:chip`}
              data-flag-type={flag.type ?? replayFlagTypeFromLabel(flag.label)}
              data-has-voice={Boolean(note)}
              data-playing={isPlayingNote}
              onClick={() => {
                if (isPlayingNote) {
                  if (voicePlaybackPaused) {
                    onResumeVoice();
                  } else {
                    onPauseVoice();
                  }
                  return;
                }
                onSeek(flag.timeMs ?? 0);
                if (note) {
                  onPlayVoice(note, flag);
                }
              }}
              onContextMenu={(event) => {
                event.preventDefault();
                onEditFlag(flag);
              }}
            >
              <strong>{formatDuration(flag.timeMs ?? 0)}</strong>
              <span>
                {isPlayingNote ? (voicePlaybackPaused ? <Play size={12} /> : <Pause size={12} />) : note ? <Mic size={12} /> : <Flag size={12} />}
                {isPlayingNote ? (voicePlaybackPaused ? "Resume audio" : "Pause audio") : replayFlagTypeLabel(flag)}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

function ReplaySlideshow({
  title,
  players,
  screenshots,
  flags,
  annotations,
  voiceNotes,
  initialIndex,
  trim,
  onFlagFrame,
  onEditFlag,
  activeLayerId,
  onAddAnnotation,
  onRemoveAnnotation,
  onRemoveAnnotations,
  onSaveTrim,
  onClearTrim,
  onClose
}: {
  title: string;
  players: string;
  screenshots: AtlasReplayViewModel["screenshots"];
  flags: ReplayFlag[];
  annotations: ReplayAnnotation[];
  voiceNotes: ReplayVoiceNote[];
  initialIndex: number;
  trim?: ReplayTrimRange;
  onFlagFrame: (screenshot: AtlasReplayViewModel["screenshots"][number]) => void;
  onEditFlag: (flag: ReplayFlag) => void;
  activeLayerId: string;
  onAddAnnotation: (annotation: ReplayAnnotation) => void;
  onRemoveAnnotation: (id: string) => void;
  onRemoveAnnotations: (ids: string[]) => void;
  onSaveTrim: (trim: ReplayTrimRange) => void;
  onClearTrim: () => void;
  onClose: () => void;
}) {
  const [index, setIndex] = useState(initialIndex);
  const [playing, setPlaying] = useState(false);
  const [speed, setSpeed] = useState("6");
  const [trimStartIndex, setTrimStartIndex] = useState(0);
  const [trimEndIndex, setTrimEndIndex] = useState(Math.max(0, screenshots.length - 1));
  const [contextMenu, setContextMenu] = useState<{ x: number; y: number; index: number } | null>(null);
  const [playbackClipId, setPlaybackClipId] = useState<string | undefined>();
  const [playbackOffsetMs, setPlaybackOffsetMs] = useState(0);
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const voicePlaybackTimerRef = useRef<number | null>(null);

  useEffect(() => {
    setIndex(Math.min(initialIndex, Math.max(0, screenshots.length - 1)));
    setPlaying(false);
  }, [initialIndex, screenshots.length]);

  useEffect(() => {
    const initialRange = trimIndexesForScreenshots(screenshots, trim);
    setTrimStartIndex(initialRange.start);
    setTrimEndIndex(initialRange.end);
  }, [screenshots, trim]);

  useEffect(() => {
    if (!playing || screenshots.length <= 1) {
      return;
    }
    const current = screenshots[index] ?? screenshots[0];
    const next = screenshots[(index + 1) % screenshots.length] ?? screenshots[0];
    const timer = window.setTimeout(() => {
      setIndex((value) => (value + 1) % screenshots.length);
    }, replayFrameDelay(current, next, Number.parseFloat(speed) || 1));
    return () => window.clearTimeout(timer);
  }, [index, playing, screenshots, speed]);

  useEffect(() => () => {
    audioRef.current?.pause();
    if (voicePlaybackTimerRef.current) {
      window.clearInterval(voicePlaybackTimerRef.current);
    }
  }, []);

  if (!screenshots.length) {
    return null;
  }

  const currentIndex = Math.min(index, Math.max(0, screenshots.length - 1));
  const current = screenshots[currentIndex] ?? screenshots[0];
  const currentFlags = flags.filter((flag) => flag.targetType === "frame" && flag.targetId === replayFrameTargetId(current));
  const currentAnnotations = annotations.filter((annotation) => annotation.targetId === replayFrameTargetId(current));
  const trimStart = Math.min(trimStartIndex, trimEndIndex);
  const trimEnd = Math.max(trimStartIndex, trimEndIndex);
  const trimmedCount = trimEnd - trimStart + 1;
  const trimActive = trimmedCount < screenshots.length;
  const move = (offset: number) => {
    setIndex((value) => (value + offset + screenshots.length) % screenshots.length);
  };
  const cutBefore = (frameIndex: number) => {
    setTrimStartIndex(frameIndex);
    if (trimEndIndex < frameIndex) {
      setTrimEndIndex(frameIndex);
    }
    setIndex(frameIndex);
    setContextMenu(null);
  };
  const cutAfter = (frameIndex: number) => {
    setTrimEndIndex(frameIndex);
    if (trimStartIndex > frameIndex) {
      setTrimStartIndex(frameIndex);
    }
    setIndex(frameIndex);
    setContextMenu(null);
  };
  const saveTrim = () => {
    const start = screenshots[trimStart];
    const end = screenshots[trimEnd];
    if (!start || !end) {
      return;
    }
    onSaveTrim({
      startCapturedAt: start.capturedAt,
      endCapturedAt: end.capturedAt,
      startFrameKey: replayFrameTargetId(start),
      endFrameKey: replayFrameTargetId(end),
      savedAt: new Date().toISOString()
    });
    setContextMenu(null);
  };
  const clearTrim = () => {
    setTrimStartIndex(0);
    setTrimEndIndex(Math.max(0, screenshots.length - 1));
    setContextMenu(null);
    onClearTrim();
  };
  const openFrameMenu = (event: React.MouseEvent, frameIndex: number) => {
    event.preventDefault();
    event.stopPropagation();
    setPlaying(false);
    setIndex(frameIndex);
    setContextMenu({ ...replayContextMenuPosition(event.clientX, event.clientY), index: frameIndex });
  };
  const stopFrameVoicePlayback = () => {
    if (voicePlaybackTimerRef.current) {
      window.clearInterval(voicePlaybackTimerRef.current);
      voicePlaybackTimerRef.current = null;
    }
    setPlaybackClipId(undefined);
    setPlaybackOffsetMs(0);
  };
  const playFrameVoice = (note: ReplayVoiceNote) => {
    if (!audioRef.current) {
      audioRef.current = new Audio();
    }
    stopFrameVoicePlayback();
    audioRef.current.pause();
    audioRef.current.src = note.dataUrl;
    audioRef.current.currentTime = 0;
    setPlaybackClipId(note.id);
    setPlaybackOffsetMs(0);
    voicePlaybackTimerRef.current = window.setInterval(() => {
      setPlaybackOffsetMs(Math.round((audioRef.current?.currentTime ?? 0) * 1000));
    }, 80);
    audioRef.current.onended = () => stopFrameVoicePlayback();
    void audioRef.current.play();
  };

  return (
    <div className="modal-backdrop replay-slideshow-backdrop" onClick={onClose} onContextMenu={(event) => event.preventDefault()}>
      <section
        className="replay-slideshow"
        onClick={(event) => {
          event.stopPropagation();
          setContextMenu(null);
        }}
      >
        <header>
          <div>
            <span>Visual replay</span>
            <h2>{title}</h2>
            <p>{players} - frame {currentIndex + 1} of {screenshots.length}</p>
          </div>
          <button type="button" className="icon-button" onClick={onClose} title="Close visual replay">
            <X size={18} />
          </button>
        </header>
        <div className="replay-slideshow-stage">
          <button type="button" className="replay-slide-nav" onClick={() => move(-1)} title="Previous frame">
            <ChevronLeft size={26} />
          </button>
          <figure>
            <div className="replay-frame-stage">
              {current.url ? <img src={current.url} alt="" /> : null}
              <ReplayAnnotationCanvas
                annotations={currentAnnotations}
                targetId={replayFrameTargetId(current)}
                targetLabel={current.label}
                capturedAt={current.capturedAt}
                layerId={activeLayerId}
                playbackClipId={playbackClipId}
                playbackOffsetMs={playbackOffsetMs}
                onAddAnnotation={onAddAnnotation}
                onRemoveAnnotation={onRemoveAnnotation}
                onRemoveAnnotations={onRemoveAnnotations}
              />
            </div>
            <figcaption>
              <strong>{current.label}</strong>
              <span>{new Date(current.capturedAt).toLocaleString()}</span>
              {currentFlags.length ? <b>{currentFlags.map((flag) => flag.label).join(", ")}</b> : null}
              <em>{current.source === "timed-replay" ? "Timed visual replay frame" : current.source}</em>
            </figcaption>
          </figure>
          <button type="button" className="replay-slide-nav" onClick={() => move(1)} title="Next frame">
            <ChevronRight size={26} />
          </button>
        </div>
        <div className="replay-player-controls">
          <button type="button" className="secondary" onClick={() => setPlaying((value) => !value)}>
            {playing ? <Pause size={16} /> : <Play size={16} />} {playing ? "Pause" : "Play"}
          </button>
          <button type="button" className="secondary" onClick={() => onFlagFrame(current)}>
            <Flag size={16} /> Flag frame
          </button>
          <label>
            Frame
            <input
              type="range"
              min="0"
              max={Math.max(0, screenshots.length - 1)}
              value={currentIndex}
              onChange={(event) => setIndex(Number.parseInt(event.target.value, 10) || 0)}
            />
          </label>
          <select value={speed} onChange={(event) => setSpeed(event.target.value)} title="Playback speed">
            <option value="0.5">0.5x</option>
            <option value="1">1x</option>
            <option value="2">2x</option>
            <option value="4">4x</option>
            <option value="6">6x</option>
            <option value="8">8x</option>
          </select>
        </div>
        {currentFlags.length ? (
          <div className="replay-frame-marker-row">
            {currentFlags.map((flag) => {
              const note = replayVoiceNoteForFlag(voiceNotes, flag.id, flag.layerId);
              return (
                <button
                  type="button"
                  key={flag.id}
                  data-has-voice={Boolean(note)}
                  data-flag-type={flag.type ?? replayFlagTypeFromLabel(flag.label)}
                  onClick={() => note ? playFrameVoice(note) : onEditFlag(flag)}
                  onContextMenu={(event) => {
                    event.preventDefault();
                    onEditFlag(flag);
                  }}
                  title={note ? "Play voice note, right-click to edit" : "Edit flag"}
                >
                  {note ? <Mic size={13} /> : <Flag size={13} />}
                  <span>{replayFlagTypeLabel(flag)}</span>
                </button>
              );
            })}
          </div>
        ) : null}
        <div className="replay-trim-controls">
          <span>{trimActive ? `Keeping ${trimmedCount} of ${screenshots.length} frames` : `All ${screenshots.length} frames kept`}</span>
          <em>Right-click the timeline to cut before or after a frame.</em>
          <button type="button" className="primary" onClick={saveTrim} disabled={!trimActive && !trim}>
            Save trim
          </button>
          <button type="button" className="secondary" onClick={clearTrim} disabled={!trimActive && !trim}>
            Clear trim
          </button>
        </div>
        <div className="replay-slide-strip">
          {screenshots.map((screenshot, thumbIndex) => {
            const thumbFlags = flags.filter((flag) => flag.targetType === "frame" && flag.targetId === replayFrameTargetId(screenshot));
            const thumbHasVoice = thumbFlags.some((flag) => replayVoiceNoteForFlag(voiceNotes, flag.id, flag.layerId));
            return (
              <button
                type="button"
                key={screenshotKey(screenshot)}
                data-active={thumbIndex === currentIndex}
                data-trim-state={trimMarkerState(thumbIndex, trimStart, trimEnd)}
                data-has-flags={Boolean(thumbFlags.length)}
                data-has-voice={thumbHasVoice}
                onClick={() => setIndex(thumbIndex)}
                onContextMenu={(event) => openFrameMenu(event, thumbIndex)}
                title={thumbFlags.length ? `${screenshot.label} - ${thumbFlags.map(replayFlagTypeLabel).join(", ")}` : screenshot.label}
              >
                {screenshot.url ? <img src={screenshot.url} alt="" loading="lazy" /> : <Camera size={16} />}
                {thumbFlags.length ? <i>{thumbHasVoice ? <Mic size={12} /> : <Flag size={12} />}</i> : null}
                <span>{thumbIndex + 1}</span>
              </button>
            );
          })}
        </div>
        {contextMenu ? (
          <div
            className="replay-frame-context-menu"
            style={{ left: contextMenu.x, top: contextMenu.y }}
            onClick={(event) => event.stopPropagation()}
          >
            <strong>Frame {contextMenu.index + 1}</strong>
            <button type="button" onClick={() => cutBefore(contextMenu.index)}>Remove everything before this</button>
            <button type="button" onClick={() => cutAfter(contextMenu.index)}>Remove everything after this</button>
            <button type="button" onClick={saveTrim}>Save current trim</button>
            <button type="button" onClick={clearTrim}>Clear trim</button>
            <button
              type="button"
              onClick={() => {
                const frame = screenshots[contextMenu.index];
                const existing = flags.find((flag) => flag.targetType === "frame" && flag.targetId === replayFrameTargetId(frame));
                if (existing) {
                  onEditFlag(existing);
                } else {
                  onFlagFrame(frame);
                }
                setContextMenu(null);
              }}
            >
              {flags.some((flag) => flag.targetType === "frame" && flag.targetId === replayFrameTargetId(screenshots[contextMenu.index])) ? "Edit frame flag" : "Flag this frame"}
            </button>
          </div>
        ) : null}
      </section>
    </div>
  );
}

function trimIndexesForScreenshots(
  screenshots: AtlasReplayViewModel["screenshots"],
  trim?: ReplayTrimRange
): { start: number; end: number } {
  if (!screenshots.length) {
    return { start: 0, end: 0 };
  }
  if (!trim) {
    return { start: 0, end: screenshots.length - 1 };
  }
  const startTime = new Date(trim.startCapturedAt).getTime();
  const endTime = new Date(trim.endCapturedAt).getTime();
  const minTime = Math.min(startTime, endTime);
  const maxTime = Math.max(startTime, endTime);
  if (!Number.isFinite(minTime) || !Number.isFinite(maxTime)) {
    return { start: 0, end: screenshots.length - 1 };
  }
  const start = screenshots.findIndex((screenshot) => new Date(screenshot.capturedAt).getTime() >= minTime);
  const end = findLastScreenshotIndexAtOrBefore(screenshots, maxTime);
  return {
    start: start >= 0 ? start : 0,
    end: end >= 0 ? end : screenshots.length - 1
  };
}

function findLastScreenshotIndexAtOrBefore(screenshots: AtlasReplayViewModel["screenshots"], time: number): number {
  for (let index = screenshots.length - 1; index >= 0; index -= 1) {
    const capturedAt = new Date(screenshots[index].capturedAt).getTime();
    if (Number.isFinite(capturedAt) && capturedAt <= time) {
      return index;
    }
  }
  return -1;
}

function trimMarkerState(index: number, start: number, end: number): "start" | "end" | "inside" | "outside" {
  if (index === start) return "start";
  if (index === end) return "end";
  if (index > start && index < end) return "inside";
  return "outside";
}

function replayContextMenuPosition(x: number, y: number): { x: number; y: number } {
  const menuWidth = 236;
  const menuHeight = 240;
  const padding = 10;
  return {
    x: Math.min(Math.max(padding, x), Math.max(padding, window.innerWidth - menuWidth - padding)),
    y: Math.min(Math.max(padding, y), Math.max(padding, window.innerHeight - menuHeight - padding))
  };
}

function replayFrameDelay(
  current: AtlasReplayViewModel["screenshots"][number],
  next: AtlasReplayViewModel["screenshots"][number],
  speed: number
): number {
  const currentAt = new Date(current.capturedAt).getTime();
  const nextAt = new Date(next.capturedAt).getTime();
  const raw = Number.isFinite(currentAt) && Number.isFinite(nextAt) && nextAt > currentAt
    ? nextAt - currentAt
    : 1800;
  return Math.round(Math.min(4500, Math.max(800, raw)) / Math.max(0.25, speed));
}

function ReplayDeckTrackerPanel({ replay, currentTimeMs }: { replay: ReplayRecord; currentTimeMs: number }) {
  const snapshots = replay.deckTrackerSnapshots ?? [];
  if (!snapshots.length) {
    return null;
  }
  const targetTime = replay.video?.startedAt
    ? new Date(replay.video.startedAt).getTime() + currentTimeMs
    : new Date(replay.capturedAt).getTime();
  const snapshot = [...snapshots].sort((a, b) => {
    const aDistance = Math.abs(new Date(a.capturedAt).getTime() - targetTime);
    const bDistance = Math.abs(new Date(b.capturedAt).getTime() - targetTime);
    return aDistance - bDistance;
  })[0] ?? snapshots.at(-1)!;
  const state = snapshot.state;
  const cards = state.cards
    .filter((card) => card.pinned || card.seenCount > 0)
    .slice(0, 8);
  const opponentCards = state.opponent.cards.slice(0, 8);
  return (
    <section className="rail-card replay-deck-tracker-panel">
      <header>
        <div>
          <h2>Deck tracker</h2>
          <span>{state.deckTitle || "Active deck"} - nearest snapshot at {new Date(snapshot.capturedAt).toLocaleTimeString()}</span>
        </div>
        <strong>{state.cardsLeft}/{state.deckSize} left</strong>
      </header>
      <div className="replay-deck-tracker-grid">
        {cards.map((card) => (
          <div className="replay-deck-tracker-card" key={card.cardKey}>
            {card.imageUrl ? <img src={card.imageUrl} alt="" loading="lazy" /> : null}
            <div>
              <strong>{card.name}</strong>
              <span>{card.copiesLeft}/{card.deckCount} left</span>
              <small>Next draw / 2 / 3: {percent(card.odds.next1)} / {percent(card.odds.next2)} / {percent(card.odds.next3)}</small>
            </div>
          </div>
        ))}
        {!cards.length ? <p className="muted">No pinned or seen cards in this snapshot.</p> : null}
      </div>
      {opponentCards.length ? (
        <>
          <header className="replay-deck-tracker-subheader">
            <strong>Opponent seen</strong>
            <span>{state.opponent.totalSeen} public card{state.opponent.totalSeen === 1 ? "" : "s"}</span>
          </header>
          <div className="replay-deck-tracker-grid">
            {opponentCards.map((card) => (
              <div className="replay-deck-tracker-card" key={`opponent-${card.cardKey}`}>
                {card.imageUrl ? <img src={card.imageUrl} alt="" loading="lazy" /> : null}
                <div>
                  <strong>{card.name}</strong>
                  <span>{card.count} seen</span>
                  <small>{card.zones.join(", ")}</small>
                </div>
              </div>
            ))}
          </div>
        </>
      ) : null}
    </section>
  );
}

